def _parse_cli_config_overrides(args: List[str]) -> Dict[str, object]:
    out: Dict[str, object] = {}
    i = 0
    while i < len(args):
        tok = str(args[i]).strip()
        if not tok.startswith("--"):
            i += 1
            continue

        key = tok[2:]
        val: Optional[str] = None

        if "=" in key:
            key, val = key.split("=", 1)
        else:
            if i + 1 < len(args) and not str(args[i + 1]).strip().startswith("--"):
                val = str(args[i + 1]).strip()
                i += 1

        key2 = key.replace("_", "-").lower()
        if val is not None:
            f = _parse_float(val)
            if f is not None:
                if key2 in {"enable-dd-stop", "dd-stop", "dd-stop-enable"}:
                    out["enable_dd_stop"] = bool(int(round(f)) != 0)
                elif key2 in {"risk-per-trade", "risk"}:
                    out["risk_per_trade"] = float(f)
                elif key2 in {"dd-stop-threshold"}:
                    out["dd_stop_threshold"] = float(abs(float(f)))
                elif key2 in {"dd-stop-allow-manual-reset"}:
                    out["dd_stop_allow_manual_reset"] = bool(int(round(f)) != 0)
                elif key2 in {"enable-dd-stop-auto-recover", "dd-stop-auto-recover"}:
                    out["enable_dd_stop_auto_recover"] = bool(int(round(f)) != 0)
                elif key2 in {"dd-stop-cooldown-bars"}:
                    out["dd_stop_cooldown_bars"] = int(round(f))
                elif key2 in {"dd-warning-threshold"}:
                    out["dd_warning_threshold"] = float(abs(float(f)))
                elif key2 in {"dd-warning-risk-mult", "dd-warning-risk-multiplier"}:
                    out["dd_warning_risk_mult"] = float(f)
                elif key2 in {"dd-stop-reset-peak-on-recover"}:
                    out["dd_stop_reset_peak_on_recover"] = bool(int(round(f)) != 0)

        i += 1

    return out


def _find_latest_deploy_csv(p0_sweep_dir: Path, prefix: str) -> Optional[Path]:
    if not p0_sweep_dir.exists():
        return None
    candidates = list(p0_sweep_dir.glob(f"{prefix}_*.csv"))
    if not candidates:
        return None
    candidates.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return candidates[0]


def _load_deploy_rows(csv_path: Path) -> List[Dict[str, str]]:
    if not csv_path.exists():
        raise FileNotFoundError(str(csv_path))
    df = pd.read_csv(csv_path, dtype=str, encoding="utf-8-sig")
    if df.empty:
        return []
    if "symbol" not in df.columns:
        raise ValueError(f"missing 'symbol' column in {csv_path}")
    keep_cols = [c for c in ["symbol", "diag_vol_state_gate", "rationale", "profile_override"] if c in df.columns]
    out = df[keep_cols].fillna("").astype(str).to_dict(orient="records")
    return out


def init_observe_csv(
    out_csv: Path,
    *,
    date_tag: str,
    deploy_core_csv: Optional[Path],
    deploy_observe_csv: Optional[Path],
    default_decision: str = "watch",
) -> Path:
    out_csv.parent.mkdir(parents=True, exist_ok=True)

    cols = [
        "date",
        "pool",
        "symbol",
        "diag_vol_state_gate",
        "defense_mode",
        "trigger",
        "decision",
        "reason",
        "evidence_out_dir",
        "entry_time_utc",
        "snapshot_price",
        "notes",
    ]

    rows: List[Dict[str, str]] = []
    for pool, csv_path in [("core", deploy_core_csv), ("observe", deploy_observe_csv)]:
        if csv_path is None:
            continue
        for r in _load_deploy_rows(csv_path):
            sym = str(r.get("symbol") or "").strip().upper()
            if not sym:
                continue
            diag_gate = str(r.get("diag_vol_state_gate") or "").strip()
            notes = str(r.get("rationale") or "").strip()
            rows.append(
                {
                    "date": date_tag,
                    "pool": pool,
                    "symbol": sym,
                    "diag_vol_state_gate": diag_gate,
                    "defense_mode": "",
                    "trigger": "",
                    "decision": default_decision,
                    "reason": "",
                    "evidence_out_dir": "",
                    "entry_time_utc": "",
                    "snapshot_price": "",
                    "notes": notes,
                }
            )

    new_df = pd.DataFrame(rows, columns=cols)
    if not new_df.empty:
        new_df = new_df.sort_values(["pool", "symbol"], kind="mergesort").reset_index(drop=True)

    if out_csv.exists():
        old = pd.read_csv(out_csv, dtype=str, encoding="utf-8-sig")
        if old.empty:
            merged = new_df.copy()
        else:
            for c in cols:
                if c not in old.columns:
                    old[c] = ""
            old = old[cols].fillna("").astype(str)
            new_df = new_df.fillna("").astype(str)
            sym_pool = {str(r["symbol"]).strip().upper(): str(r["pool"]) for r in new_df.to_dict(orient="records")}
            sym_diag_gate = {str(r["symbol"]).strip().upper(): str(r["diag_vol_state_gate"]) for r in new_df.to_dict(orient="records")}
            sym_notes = {str(r["symbol"]).strip().upper(): str(r["notes"]) for r in new_df.to_dict(orient="records")}

            old_sym = old["symbol"].astype(str).str.strip().str.upper()
            old_date = old["date"].astype(str).str.strip()
            old_pool = old["pool"].astype(str).str.strip()
            old_decision = old["decision"].astype(str).str.strip()
            old_gate = old["diag_vol_state_gate"].astype(str).str.strip()
            old_notes = old["notes"].astype(str).str.strip()

            old.loc[old_date == "", "date"] = date_tag
            old.loc[old_pool == "", "pool"] = old_sym.map(sym_pool).fillna("")
            old.loc[old_decision == "", "decision"] = default_decision
            old.loc[old_gate == "", "diag_vol_state_gate"] = old_sym.map(sym_diag_gate).fillna("")
            old.loc[old_notes == "", "notes"] = old_sym.map(sym_notes).fillna("")

            key_cols = ["date", "pool", "symbol"]
            key_old = set(tuple(x) for x in old[key_cols].to_numpy().tolist())
            to_add = new_df[~new_df[key_cols].apply(tuple, axis=1).isin(key_old)].copy()
            merged = pd.concat([old, to_add], ignore_index=True)
            merged = merged.fillna("").astype(str)
            non_empty = (merged[cols] != "").sum(axis=1).astype(int)
            merged = merged.assign(_non_empty=non_empty).sort_values(
                ["date", "pool", "symbol", "_non_empty"], kind="mergesort"
            )
            merged = merged.drop_duplicates(subset=["date", "pool", "symbol"], keep="last").drop(columns=["_non_empty"])
            merged = merged.sort_values(["date", "pool", "symbol"], kind="mergesort").reset_index(drop=True)
        merged.to_csv(out_csv, index=False, encoding="utf-8-sig")
        return out_csv

    new_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    return out_csv


def _iter_trades_baseline_csvs(p0_sweep_dir: Path) -> List[Path]:
    if not p0_sweep_dir.exists():
        return []
    files = [p for p in p0_sweep_dir.glob("**/trades_baseline_*.csv") if p.is_file() and p.stat().st_size > 0]
    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return files


def _safe_spearman_corr(x: pd.Series, y: pd.Series) -> float:
    xs = pd.to_numeric(x, errors="coerce")
    ys = pd.to_numeric(y, errors="coerce")
    m = xs.notna() & ys.notna()
    if int(m.sum()) < 10:
        return float("nan")
    if float(xs[m].nunique()) <= 1.0:
        return float("nan")
    if float(ys[m].nunique()) <= 1.0:
        return float("nan")
    return float(xs[m].corr(ys[m], method="spearman"))


def _summarize_trades_file(trades_csv: Path, p0_sweep_dir: Path) -> Tuple[Dict[str, object], pd.DataFrame]:
    rel = trades_csv.relative_to(p0_sweep_dir)
    parts = list(rel.parts)
    symbol = parts[0] if len(parts) >= 1 else ""
    split = parts[1] if len(parts) >= 2 else ""
    profile = parts[2] if len(parts) >= 3 else ""

    usecols = [
        "entry_time",
        "side",
        "entry",
        "signal",
        "exit_time",
        "exit",
        "size",
        "pnl",
        "reason",
        "sv_bias",
        "sv_regime_code",
        "entry_vol_ratio",
        "sv_risk_on_mkt",
        "sv_use_struct_vote",
        "sv_votes_long",
        "sv_votes_short",
        "sv_votes_long_3",
        "sv_votes_short_3",
        "sv_votes_long_4",
        "sv_votes_short_4",
        "sv_bb_ratio_4h",
        "sv_atr_ratio_1h",
        "sv_swing_high_4h",
        "sv_swing_low_4h",
        "atr",
        "stop",
        "entry_score",
        "size_mult",
        "e1_break_strength_atr",
        "e1_retest_depth_atr",
        "e1_retest_bars",
        "e1_atr_ratio",
        "k",
        "N",
        "M",
        "X",
        "body_k",
        "touch_k",
        "shadow_k",
        "stop_k",
        "risk_per_trade",
    ]
    try:
        df = pd.read_csv(trades_csv, dtype=str, encoding="utf-8-sig", usecols=lambda c: c in set(usecols))
    except pd.errors.EmptyDataError:
        run_row = {
            "symbol": symbol,
            "split": split,
            "profile": profile,
            "trades_csv": str(trades_csv),
            "ok": False,
            "error": "empty_file",
        }
        return run_row, pd.DataFrame()
    except Exception:
        try:
            df = pd.read_csv(trades_csv, dtype=str, encoding="utf-8-sig")
        except pd.errors.EmptyDataError:
            run_row = {
                "symbol": symbol,
                "split": split,
                "profile": profile,
                "trades_csv": str(trades_csv),
                "ok": False,
                "error": "empty_file",
            }
            return run_row, pd.DataFrame()

    if df.empty or "entry_time" not in df.columns:
        run_row = {
            "symbol": symbol,
            "split": split,
            "profile": profile,
            "trades_csv": str(trades_csv),
            "ok": False,
            "error": "empty_or_missing_entry_time",
        }
        return run_row, pd.DataFrame()

    for c in ["signal", "reason", "side", "entry", "exit_time", "pnl"]:
        if c not in df.columns:
            df[c] = ""
    df = df.fillna("").astype(str)

    key_cols = ["entry_time", "side", "entry"]
    is_entry = df["signal"].astype(str).str.strip().ne("")
    entry_rows = df[is_entry].drop_duplicates(subset=key_cols, keep="last").copy()

    pnl = pd.to_numeric(df["pnl"], errors="coerce")
    pnl0 = pnl.fillna(0.0)
    reason_s = df["reason"].astype(str).str.strip()
    is_tp1 = reason_s.isin(["tp_cam_r1", "tp_cam_s1"])
    is_tp2 = reason_s.isin(["tp_cam_r2", "tp_cam_s2"])
    is_stop = reason_s.str.contains("stop", case=False, na=False)
    is_stop_loss = is_stop & (pnl0 < 0.0)
    is_stop_be = is_stop & (pnl0 == 0.0)

    entry_dt = pd.to_datetime(df["entry_time"], utc=True, errors="coerce")
    exit_dt = pd.to_datetime(df["exit_time"], utc=True, errors="coerce")

    pnl_sum = pnl.groupby([df[k] for k in key_cols], sort=False).sum(min_count=1)
    tp1_any = is_tp1.groupby([df[k] for k in key_cols], sort=False).any()
    tp2_any = is_tp2.groupby([df[k] for k in key_cols], sort=False).any()
    stop_any = is_stop.groupby([df[k] for k in key_cols], sort=False).any()
    stop_loss_any = is_stop_loss.groupby([df[k] for k in key_cols], sort=False).any()
    stop_be_any = is_stop_be.groupby([df[k] for k in key_cols], sort=False).any()
    max_exit = exit_dt.groupby([df[k] for k in key_cols], sort=False).max()
    min_entry = entry_dt.groupby([df[k] for k in key_cols], sort=False).min()

    trade_level = (
        pd.DataFrame(
            {
                "entry_time": pnl_sum.index.get_level_values(0).astype(str),
                "side": pnl_sum.index.get_level_values(1).astype(str),
                "entry": pnl_sum.index.get_level_values(2).astype(str),
                "trade_pnl": pnl_sum.to_numpy(),
                "tp1_any": tp1_any.to_numpy(dtype=bool),
                "tp2_any": tp2_any.to_numpy(dtype=bool),
                "stop_any": stop_any.to_numpy(dtype=bool),
                "stop_loss_any": stop_loss_any.to_numpy(dtype=bool),
                "stop_be_any": stop_be_any.to_numpy(dtype=bool),
                "max_exit_time": max_exit.to_numpy(),
                "min_entry_time": min_entry.to_numpy(),
            }
        )
        .fillna({"trade_pnl": 0.0})
        .copy()
    )
    trade_level["win"] = pd.to_numeric(trade_level["trade_pnl"], errors="coerce").fillna(0.0) > 0.0
    hold = pd.to_datetime(trade_level["max_exit_time"], utc=True, errors="coerce") - pd.to_datetime(
        trade_level["min_entry_time"], utc=True, errors="coerce"
    )
    trade_level["hold_hours"] = hold.dt.total_seconds() / 3600.0
    trade_level.drop(columns=["max_exit_time", "min_entry_time"], inplace=True)

    feats = entry_rows.copy()
    feat_cols = [c for c in usecols if c in feats.columns and c not in set(key_cols + ["signal", "exit_time", "exit", "pnl", "reason", "size"])]
    feats = feats[key_cols + feat_cols].copy()
    merged = trade_level.merge(feats, on=key_cols, how="left")

    n_trades = int(len(merged))
    total_pnl = float(pd.to_numeric(merged["trade_pnl"], errors="coerce").fillna(0.0).sum()) if n_trades else 0.0
    win_rate = float(pd.to_numeric(merged["win"], errors="coerce").mean()) if n_trades else 0.0
    avg_pnl = float(pd.to_numeric(merged["trade_pnl"], errors="coerce").mean()) if n_trades else 0.0
    tp1_rate = float(pd.to_numeric(merged["tp1_any"], errors="coerce").mean()) if n_trades else 0.0
    tp2_rate = float(pd.to_numeric(merged["tp2_any"], errors="coerce").mean()) if n_trades else 0.0
    stop_rate = float(pd.to_numeric(merged["stop_any"], errors="coerce").mean()) if n_trades else 0.0
    stop_loss_rate = float(pd.to_numeric(merged["stop_loss_any"], errors="coerce").mean()) if n_trades else 0.0
    stop_be_rate = float(pd.to_numeric(merged["stop_be_any"], errors="coerce").mean()) if n_trades else 0.0
    hold_median_h = float(pd.to_numeric(merged["hold_hours"], errors="coerce").median()) if n_trades else float("nan")

    run_row: Dict[str, object] = {
        "symbol": symbol,
        "split": split,
        "profile": profile,
        "trades_csv": str(trades_csv),
        "n_trades": float(n_trades),
        "total_pnl": total_pnl,
        "avg_pnl": avg_pnl,
        "win_rate": win_rate,
        "tp1_rate": tp1_rate,
        "tp2_rate": tp2_rate,
        "stop_rate": stop_rate,
        "stop_loss_rate": stop_loss_rate,
        "stop_be_rate": stop_be_rate,
        "hold_hours_median": hold_median_h,
        "ok": True,
        "error": "",
    }

    feature_rows: List[Dict[str, object]] = []
    for fcol in feat_cols:
        raw = merged[fcol].fillna("").astype(str).str.strip()
        xs = pd.to_numeric(raw, errors="coerce")
        ys = pd.to_numeric(merged["trade_pnl"], errors="coerce")
        m = xs.notna() & ys.notna()
        n = int(m.sum())
        if n < 10:
            x2 = raw.str.lower().map({"true": 1.0, "false": 0.0, "1": 1.0, "0": 0.0})
            m2 = x2.notna() & ys.notna()
            n2 = int(m2.sum())
            if n2 >= 10 and float(x2[m2].nunique()) > 1.0:
                xs = x2
                m = m2
                n = n2
            else:
                continue
        if float(xs[m].nunique()) <= 1.0:
            continue
        q25 = float(xs[m].quantile(0.25))
        q75 = float(xs[m].quantile(0.75))
        bot = float(ys[m & (xs <= q25)].mean()) if float((m & (xs <= q25)).sum()) >= 5.0 else float("nan")
        top = float(ys[m & (xs >= q75)].mean()) if float((m & (xs >= q75)).sum()) >= 5.0 else float("nan")
        effect = top - bot if (pd.notna(top) and pd.notna(bot)) else float("nan")

        row = {
            "symbol": symbol,
            "split": split,
            "profile": profile,
            "trades_csv": str(trades_csv),
            "feature": fcol,
            "n": float(n),
            "spearman_pnl": _safe_spearman_corr(xs, ys),
            "top_q_pnl_mean": top,
            "bot_q_pnl_mean": bot,
            "top_minus_bot": effect,
            "spearman_tp2": _safe_spearman_corr(xs, merged["tp2_any"].astype(int)),
            "spearman_stop_loss": _safe_spearman_corr(xs, merged["stop_loss_any"].astype(int)),
            "spearman_stop_be": _safe_spearman_corr(xs, merged["stop_be_any"].astype(int)),
        }
        feature_rows.append(row)

    feat_df = pd.DataFrame(feature_rows)
    return run_row, feat_df


def run_indicator_audit(
    *,
    p0_sweep_dir: Path,
    out_dir: Path,
    max_files: int = 0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    if max_files > 0:
        files = files[: int(max_files)]

    run_rows: List[Dict[str, object]] = []
    feat_frames: List[pd.DataFrame] = []
    for p in files:
        rr, ff = _summarize_trades_file(p, p0_sweep_dir)
        run_rows.append(rr)
        if not ff.empty:
            feat_frames.append(ff)

    runs_df = pd.DataFrame(run_rows)
    feats_df = pd.concat(feat_frames, ignore_index=True) if feat_frames else pd.DataFrame()

    runs_csv = out_dir / "indicator_audit_runs.csv"
    feats_csv = out_dir / "indicator_audit_features.csv"
    runs_df.to_csv(runs_csv, index=False, encoding="utf-8-sig")
    feats_df.to_csv(feats_csv, index=False, encoding="utf-8-sig")

    return {"RUNS": runs_csv, "FEATURES": feats_csv}


def _extract_symbol_split_profile(trades_csv: Path, p0_sweep_dir: Path) -> Tuple[str, str, str]:
    rel = trades_csv.relative_to(p0_sweep_dir)
    parts = list(rel.parts)
    if not parts:
        return "", "", ""

    def _is_split_seg(s: str) -> bool:
        s2 = str(s or "").strip().lower()
        if not s2:
            return False
        if s2 in {"since2022", "pre2022", "all", "full"}:
            return True
        if re.fullmatch(r"(since|pre)\d{4}", s2):
            return True
        if re.fullmatch(r"\d{4}to\d{4}", s2):
            return True
        return False

    if len(parts) >= 4 and _is_split_seg(parts[1]):
        symbol = parts[0]
        split = parts[1]
        profile = parts[2]
        return symbol, split, profile

    if len(parts) >= 5 and _is_split_seg(parts[2]):
        symbol = parts[1]
        split = parts[2]
        profile = parts[3]
        return symbol, split, profile

    symbol = parts[0] if len(parts) >= 1 else ""
    split = parts[1] if len(parts) >= 2 else ""
    profile = parts[2] if len(parts) >= 3 else ""
    return symbol, split, profile


def _iter_trades_baseline_csvs_latest(p0_sweep_dir: Path) -> List[Path]:
    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    if not files:
        return []
    chosen: Dict[Tuple[str, str, str], Path] = {}
    for p in files:
        key = _extract_symbol_split_profile(p, p0_sweep_dir)
        prev = chosen.get(key)
        if prev is None or p.stat().st_mtime > prev.stat().st_mtime:
            chosen[key] = p
    out = list(chosen.values())
    out.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return out


def _trade_level_merged_for_features(trades_csv: Path, p0_sweep_dir: Path, feat_cols: List[str]) -> pd.DataFrame:
    key_cols = ["entry_time", "side", "entry"]
    usecols = [
        "entry_time",
        "side",
        "entry",
        "signal",
        "exit_time",
        "pnl",
        "reason",
        *feat_cols,
    ]
    df = pd.read_csv(trades_csv, dtype=str, encoding="utf-8-sig", usecols=lambda c: c in set(usecols))
    if df.empty or "entry_time" not in df.columns:
        return pd.DataFrame()

    for c in ["signal", "reason", "side", "entry", "exit_time", "pnl"]:
        if c not in df.columns:
            df[c] = ""
    df = df.fillna("").astype(str)

    is_entry = df["signal"].astype(str).str.strip().ne("")
    entry_rows = df[is_entry].drop_duplicates(subset=key_cols, keep="last").copy()

    pnl = pd.to_numeric(df["pnl"], errors="coerce")
    pnl0 = pnl.fillna(0.0)
    reason_s = df["reason"].astype(str).str.strip()
    is_tp1 = reason_s.isin(["tp_cam_r1", "tp_cam_s1"])
    is_tp2 = reason_s.isin(["tp_cam_r2", "tp_cam_s2"])
    is_trail = reason_s.str.contains("trail", case=False, na=False)
    is_extreme_stop = reason_s.str.contains("extreme_stop", case=False, na=False)
    is_stop = reason_s.str.contains("stop", case=False, na=False)
    is_stop_loss = is_stop & (pnl0 < 0.0)
    is_stop_be = is_stop & (pnl0 == 0.0)

    entry_dt = pd.to_datetime(df["entry_time"], utc=True, errors="coerce")
    exit_dt = pd.to_datetime(df["exit_time"], utc=True, errors="coerce")

    pnl_sum = pnl.groupby([df[k] for k in key_cols], sort=False).sum(min_count=1)
    tp1_any = is_tp1.groupby([df[k] for k in key_cols], sort=False).any()
    tp2_any = is_tp2.groupby([df[k] for k in key_cols], sort=False).any()
    trail_any = is_trail.groupby([df[k] for k in key_cols], sort=False).any()
    extreme_stop_any = is_extreme_stop.groupby([df[k] for k in key_cols], sort=False).any()
    stop_any = is_stop.groupby([df[k] for k in key_cols], sort=False).any()
    stop_loss_any = is_stop_loss.groupby([df[k] for k in key_cols], sort=False).any()
    stop_be_any = is_stop_be.groupby([df[k] for k in key_cols], sort=False).any()
    max_exit = exit_dt.groupby([df[k] for k in key_cols], sort=False).max()
    min_entry = entry_dt.groupby([df[k] for k in key_cols], sort=False).min()
    exit_leg_count = (~is_entry).groupby([df[k] for k in key_cols], sort=False).sum()

    exit_rows = df.loc[~is_entry, key_cols].copy()
    exit_rows["_exit_dt"] = exit_dt.loc[~is_entry]
    exit_rows["_ord"] = np.arange(len(df), dtype=int)[~is_entry.to_numpy(dtype=bool)]
    exit_rows["_reason"] = reason_s.loc[~is_entry].astype(str)
    exit_rows["_pnl0"] = pnl0.loc[~is_entry].astype(float)
    if not exit_rows.empty:
        exit_rows = exit_rows.sort_values(key_cols + ["_exit_dt", "_ord"], kind="mergesort")
        final_exit = exit_rows.groupby(key_cols, sort=False).tail(1).copy()
        final_exit_reason = final_exit.set_index(key_cols)["_reason"].astype(str)
        final_exit_reason = final_exit_reason.reindex(pnl_sum.index).fillna("").astype(str)
        final_exit_pnl = pd.to_numeric(final_exit.set_index(key_cols)["_pnl0"], errors="coerce").reindex(pnl_sum.index)
    else:
        final_exit_reason = pd.Series("", index=pnl_sum.index, dtype=str)
        final_exit_pnl = pd.Series(np.nan, index=pnl_sum.index, dtype=float)

    def _classify_final_exit(reason: str, pnl_value: float) -> str:
        rr = str(reason or "").strip().lower()
        if "trail" in rr:
            return "trail_stop"
        if rr in {"tp_cam_r2", "tp_cam_s2"}:
            return "tp2"
        if rr in {"tp_cam_r1", "tp_cam_s1"}:
            return "tp1"
        if "extreme_stop" in rr:
            return "extreme_stop"
        if "stop" in rr and np.isfinite(float(pnl_value)):
            if float(pnl_value) < 0.0:
                return "stop_loss"
            if float(pnl_value) == 0.0:
                return "stop_be"
            return "stop_other"
        return "other"

    final_exit_group = pd.Series(
        [_classify_final_exit(r, p) for r, p in zip(final_exit_reason.tolist(), final_exit_pnl.tolist())],
        index=pnl_sum.index,
        dtype=str,
    )
    close_partial_any = ((pd.to_numeric(exit_leg_count, errors="coerce").fillna(0.0) > 1.0) | tp1_any.fillna(False)).reindex(pnl_sum.index)

    trade_level = (
        pd.DataFrame(
            {
                "entry_time": pnl_sum.index.get_level_values(0).astype(str),
                "side": pnl_sum.index.get_level_values(1).astype(str),
                "entry": pnl_sum.index.get_level_values(2).astype(str),
                "trade_pnl": pnl_sum.to_numpy(),
                "tp1_any": tp1_any.reindex(pnl_sum.index).to_numpy(dtype=bool),
                "tp2_any": tp2_any.to_numpy(dtype=bool),
                "trail_stop_hit_any": trail_any.reindex(pnl_sum.index).to_numpy(dtype=bool),
                "extreme_stop_any": extreme_stop_any.reindex(pnl_sum.index).to_numpy(dtype=bool),
                "stop_any": stop_any.reindex(pnl_sum.index).to_numpy(dtype=bool),
                "stop_loss_any": stop_loss_any.to_numpy(dtype=bool),
                "stop_be_any": stop_be_any.reindex(pnl_sum.index).to_numpy(dtype=bool),
                "close_partial_any": close_partial_any.to_numpy(dtype=bool),
                "exit_legs": pd.to_numeric(exit_leg_count, errors="coerce").reindex(pnl_sum.index).to_numpy(),
                "exit_reason_final": final_exit_reason.to_numpy(dtype=str),
                "exit_reason_group": final_exit_group.to_numpy(dtype=str),
                "max_exit_time": max_exit.to_numpy(),
                "min_entry_time": min_entry.to_numpy(),
            }
        )
        .fillna({"trade_pnl": 0.0})
        .copy()
    )
    trade_level["win"] = pd.to_numeric(trade_level["trade_pnl"], errors="coerce").fillna(0.0) > 0.0
    hold = pd.to_datetime(trade_level["max_exit_time"], utc=True, errors="coerce") - pd.to_datetime(
        trade_level["min_entry_time"], utc=True, errors="coerce"
    )
    trade_level["hold_hours"] = hold.dt.total_seconds() / 3600.0
    hold_hours_num = pd.to_numeric(trade_level["hold_hours"], errors="coerce")
    trade_level["bars_to_exit"] = np.where(hold_hours_num.notna(), np.ceil(hold_hours_num), np.nan)
    trade_level.drop(columns=["max_exit_time", "min_entry_time"], inplace=True)

    feats = entry_rows[key_cols + [c for c in feat_cols if c in entry_rows.columns]].copy()
    merged = trade_level.merge(feats, on=key_cols, how="left")
    return merged


def _load_symbols_from_deploy(csv_path: Optional[Path]) -> List[str]:
    if csv_path is None:
        return []
    rows = _load_deploy_rows(csv_path)
    out = []
    for r in rows:
        s = str(r.get("symbol") or "").strip().upper()
        if s:
            out.append(s)
    return out


def _is_int_like_series(x: pd.Series) -> bool:
    xs = pd.to_numeric(x, errors="coerce").dropna()
    if xs.empty:
        return False
    if float(xs.nunique()) > 10.0:
        return False
    return bool(((xs - xs.round()).abs() < 1e-9).all())


def _add_bucket_rows(
    rows: List[Dict[str, object]],
    *,
    symbol: str,
    split: str,
    profile: str,
    feature: str,
    scheme: str,
    bucket_id: str,
    bucket_range: str,
    g: pd.DataFrame,
) -> None:
    n = int(len(g))
    if n <= 0:
        return
    rows.append(
        {
            "symbol": symbol,
            "split": split,
            "profile": profile,
            "feature": feature,
            "scheme": scheme,
            "bucket": bucket_id,
            "bucket_range": bucket_range,
            "n_trades": float(n),
            "win_rate": float(pd.to_numeric(g["win"], errors="coerce").mean()),
            "avg_pnl": float(pd.to_numeric(g["trade_pnl"], errors="coerce").mean()),
            "stop_loss_rate": float(pd.to_numeric(g["stop_loss_any"], errors="coerce").mean()),
            "tp2_rate": float(pd.to_numeric(g["tp2_any"], errors="coerce").mean()),
            "hold_hours_median": float(pd.to_numeric(g["hold_hours"], errors="coerce").median()),
        }
    )


def run_b30_evidence(
    *,
    p0_sweep_dir: Path,
    out_dir: Path,
    scope: str = "core_observe",
    split_filter: str = "since2022",
    date_tag: str,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    b30_features = [
        "sv_atr_ratio_1h",
        "sv_bias",
        "sv_votes_short",
        "sv_votes_short_4",
        "sv_votes_long",
        "sv_votes_long_4",
        "sv_bb_ratio_4h",
        "sv_regime_code",
    ]

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")

    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, b30_features)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        for feat in b30_features:
            if feat not in merged.columns:
                continue
            x_num = pd.to_numeric(merged[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue

            dfm = merged[m].copy()
            dfm["_x"] = x_num[m].astype(float).to_numpy()

            if feat == "sv_regime_code":
                for v, g in dfm.groupby("_x", sort=True):
                    _add_bucket_rows(
                        bucket_rows,
                        symbol=sym_u,
                        split=str(split).strip(),
                        profile=str(profile).strip(),
                        feature=feat,
                        scheme="code",
                        bucket_id=f"code={int(round(float(v)))}",
                        bucket_range="",
                        g=g,
                    )
                continue

            if feat.startswith("sv_votes_") and _is_int_like_series(dfm["_x"]):
                xv = dfm["_x"].round().astype(int)
                bucket = pd.Series(index=xv.index, dtype=str)
                bucket.loc[xv <= 1] = "low(0-1)"
                bucket.loc[xv == 2] = "mid(2)"
                bucket.loc[xv >= 3] = "high(3-4)"
                dfm["_bucket"] = bucket
                for b, g in dfm.groupby("_bucket", sort=True):
                    _add_bucket_rows(
                        bucket_rows,
                        symbol=sym_u,
                        split=str(split).strip(),
                        profile=str(profile).strip(),
                        feature=feat,
                        scheme="votes_01234",
                        bucket_id=str(b),
                        bucket_range="",
                        g=g,
                    )
                continue

            if feat == "sv_bias" and _is_int_like_series(dfm["_x"]):
                xv = dfm["_x"].round().astype(int)
                dfm["_bucket"] = xv.map(lambda z: f"bias={int(z)}")
                for b, g in dfm.groupby("_bucket", sort=True):
                    _add_bucket_rows(
                        bucket_rows,
                        symbol=sym_u,
                        split=str(split).strip(),
                        profile=str(profile).strip(),
                        feature=feat,
                        scheme="bias_code",
                        bucket_id=str(b),
                        bucket_range="",
                        g=g,
                    )
                continue

            q = 10 if feat == "sv_atr_ratio_1h" else 4
            uniq = float(dfm["_x"].nunique())
            if q == 10 and (int(len(dfm)) < 50 or uniq < 10.0):
                q = 4
            if int(len(dfm)) < 20 or uniq < 4.0:
                continue

            try:
                cat = pd.qcut(dfm["_x"], q=q, duplicates="drop")
            except Exception:
                continue
            q_actual = int(getattr(cat, "cat").categories.size)
            dfm["_bucket_id"] = (cat.cat.codes.astype(int) + 1).map(lambda z: f"q{q_actual}_bin{int(z)}")
            dfm["_bucket_range"] = cat.astype(str)
            scheme = "deciles10" if q == 10 else "qtiles4"
            for b, g in dfm.groupby("_bucket_id", sort=True):
                br = str(g["_bucket_range"].iloc[0]) if "_bucket_range" in g.columns and int(len(g)) > 0 else ""
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme=scheme,
                    bucket_id=str(b),
                    bucket_range=br,
                    g=g,
                )

    buckets_df = pd.DataFrame(bucket_rows)
    buckets_df.insert(0, "scope", scope_id) if not buckets_df.empty else None
    out_csv = out_dir / f"b30_bucket_stats_{date_tag}_v1.csv"
    summary_csv = out_dir / f"b30_feature_summary_{date_tag}_v1.csv"

    if buckets_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "symbol",
                "split",
                "profile",
                "feature",
                "scheme",
                "bucket",
                "n_trades",
                "win_rate",
                "avg_pnl",
                "stop_loss_rate",
                "tp2_rate",
                "hold_hours_median",
            ]
        ).to_csv(out_csv, index=False, encoding="utf-8-sig")
        pd.DataFrame(columns=["scope", "feature", "scheme", "n_trades", "top_minus_bot_avg_pnl", "notes"]).to_csv(
            summary_csv, index=False, encoding="utf-8-sig"
        )
        return {"BUCKETS": out_csv, "SUMMARY": summary_csv}

    buckets_df.to_csv(out_csv, index=False, encoding="utf-8-sig")

    summ_rows: List[Dict[str, object]] = []
    for (feat, scheme), sub in buckets_df.groupby(["feature", "scheme"], observed=True):
        sub2 = sub.copy()
        sub2["avg_pnl"] = pd.to_numeric(sub2["avg_pnl"], errors="coerce")
        sub2["n_trades"] = pd.to_numeric(sub2["n_trades"], errors="coerce").fillna(0.0)
        sub2 = sub2[sub2["avg_pnl"].notna() & (sub2["n_trades"] > 0)].copy()
        if sub2.empty:
            continue
        top = sub2.sort_values(["avg_pnl"], ascending=False, kind="mergesort").head(1)
        bot = sub2.sort_values(["avg_pnl"], ascending=True, kind="mergesort").head(1)
        top_p = float(top["avg_pnl"].iloc[0])
        bot_p = float(bot["avg_pnl"].iloc[0])
        summ_rows.append(
            {
                "scope": scope_id,
                "feature": feat,
                "scheme": scheme,
                "n_trades": float(sub2["n_trades"].sum()),
                "top_minus_bot_avg_pnl": float(top_p - bot_p),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(summary_csv, index=False, encoding="utf-8-sig")

    return {"BUCKETS": out_csv, "SUMMARY": summary_csv}


def run_b30_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b30_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b30_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _bin_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"bin(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = 20.0

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        sub2 = sub.copy()
        if scheme in {"deciles10", "qtiles4"}:
            sub2["_bin"] = sub2["bucket"].map(_bin_idx)
            sub2 = sub2[sub2["_bin"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_bin"] = sub2["_bin"].astype(int)
            lo = sub2.loc[sub2["_bin"].idxmin()]
            hi = sub2.loc[sub2["_bin"].idxmax()]
            if float(lo["n_trades"]) <= 0.0 or float(hi["n_trades"]) <= 0.0:
                continue
            sufficient = bool(float(lo["n_trades"]) >= min_n and float(hi["n_trades"]) >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": str(lo["bucket"]),
                    "group_b": str(hi["bucket"]),
                    "n_a": float(lo["n_trades"]),
                    "n_b": float(hi["n_trades"]),
                    "avg_pnl_a": float(lo["avg_pnl"]),
                    "avg_pnl_b": float(hi["avg_pnl"]),
                    "stop_loss_rate_a": float(lo["stop_loss_rate"]),
                    "stop_loss_rate_b": float(hi["stop_loss_rate"]),
                    "win_rate_a": float(lo["win_rate"]),
                    "win_rate_b": float(hi["win_rate"]),
                    "tp2_rate_a": float(lo["tp2_rate"]),
                    "tp2_rate_b": float(hi["tp2_rate"]),
                    "delta_avg_pnl": float(hi["avg_pnl"] - lo["avg_pnl"]),
                    "delta_stop_loss_rate": float(hi["stop_loss_rate"] - lo["stop_loss_rate"]),
                    "delta_win_rate": float(hi["win_rate"] - lo["win_rate"]),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )
            continue

        if feat == "sv_regime_code" and scheme == "code":
            sub2["_code"] = sub2["bucket"].astype(str).str.extract(r"code=(\d+)")[0]
            sub2["_code"] = pd.to_numeric(sub2["_code"], errors="coerce")
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            a = sub2[sub2["_code"].round().astype(int).eq(0)].copy()
            b = sub2[sub2["_code"].round().astype(int).ne(0)].copy()
            if a.empty or b.empty:
                continue
            aa = _agg_rows(a)
            bb = _agg_rows(b)
            sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code=0",
                    "group_b": "code!=0",
                    "n_a": aa["n"],
                    "n_b": bb["n"],
                    "avg_pnl_a": aa["avg_pnl"],
                    "avg_pnl_b": bb["avg_pnl"],
                    "stop_loss_rate_a": aa["stop_loss_rate"],
                    "stop_loss_rate_b": bb["stop_loss_rate"],
                    "win_rate_a": aa["win_rate"],
                    "win_rate_b": bb["win_rate"],
                    "tp2_rate_a": aa["tp2_rate"],
                    "tp2_rate_b": bb["tp2_rate"],
                    "delta_avg_pnl": float(bb["avg_pnl"] - aa["avg_pnl"]),
                    "delta_stop_loss_rate": float(bb["stop_loss_rate"] - aa["stop_loss_rate"]),
                    "delta_win_rate": float(bb["win_rate"] - aa["win_rate"]),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )
            continue

        if scheme == "votes_01234":
            a = sub2[sub2["bucket"].astype(str).eq("low(0-1)")].copy()
            b = sub2[sub2["bucket"].astype(str).eq("high(3-4)")].copy()
            if a.empty or b.empty:
                continue
            aa = _agg_rows(a)
            bb = _agg_rows(b)
            sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "low(0-1)",
                    "group_b": "high(3-4)",
                    "n_a": aa["n"],
                    "n_b": bb["n"],
                    "avg_pnl_a": aa["avg_pnl"],
                    "avg_pnl_b": bb["avg_pnl"],
                    "stop_loss_rate_a": aa["stop_loss_rate"],
                    "stop_loss_rate_b": bb["stop_loss_rate"],
                    "win_rate_a": aa["win_rate"],
                    "win_rate_b": bb["win_rate"],
                    "tp2_rate_a": aa["tp2_rate"],
                    "tp2_rate_b": bb["tp2_rate"],
                    "delta_avg_pnl": float(bb["avg_pnl"] - aa["avg_pnl"]),
                    "delta_stop_loss_rate": float(bb["stop_loss_rate"] - aa["stop_loss_rate"]),
                    "delta_win_rate": float(bb["win_rate"] - aa["win_rate"]),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )
            continue

        if scheme == "bias_code":
            a = sub2[sub2["bucket"].astype(str).eq("bias=-1")].copy()
            b = sub2[sub2["bucket"].astype(str).eq("bias=1")].copy()
            if a.empty or b.empty:
                continue
            aa = _agg_rows(a)
            bb = _agg_rows(b)
            sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "bias=-1",
                    "group_b": "bias=1",
                    "n_a": aa["n"],
                    "n_b": bb["n"],
                    "avg_pnl_a": aa["avg_pnl"],
                    "avg_pnl_b": bb["avg_pnl"],
                    "stop_loss_rate_a": aa["stop_loss_rate"],
                    "stop_loss_rate_b": bb["stop_loss_rate"],
                    "win_rate_a": aa["win_rate"],
                    "win_rate_b": bb["win_rate"],
                    "tp2_rate_a": aa["tp2_rate"],
                    "tp2_rate_b": bb["tp2_rate"],
                    "delta_avg_pnl": float(bb["avg_pnl"] - aa["avg_pnl"]),
                    "delta_stop_loss_rate": float(bb["stop_loss_rate"] - aa["stop_loss_rate"]),
                    "delta_win_rate": float(bb["win_rate"] - aa["win_rate"]),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )
            continue

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    summ_rows: List[Dict[str, object]] = []
    if not pairs_df.empty:
        for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], sort=True):
            g2 = g[pd.to_numeric(g["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)].copy()
            if g2.empty:
                summ_rows.append(
                    {
                        "scope": scope_id,
                        "split": split_id,
                        "feature": str(feat),
                        "scheme": str(scheme),
                        "n_pairs": float(len(g)),
                        "n_sufficient": 0.0,
                        "frac_pnl_better": float("nan"),
                        "frac_stop_loss_better": float("nan"),
                        "frac_both": float("nan"),
                        "notes": "no sufficient pairs",
                    }
                )
                continue
            pnl_better = pd.to_numeric(g2["delta_avg_pnl"], errors="coerce") > 0.0
            sl_better = pd.to_numeric(g2["delta_stop_loss_rate"], errors="coerce") < 0.0
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": float(len(g2)),
                    "frac_pnl_better": float(pnl_better.mean()),
                    "frac_stop_loss_better": float(sl_better.mean()),
                    "frac_both": float((pnl_better & sl_better).mean()),
                    "notes": "",
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b30_mae_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    features = ["sv_atr_ratio_1h", "sv_bb_ratio_4h"]
    need_cols = ["atr", *features]

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    def _add_row(
        rows: List[Dict[str, object]],
        *,
        symbol: str,
        split: str,
        profile: str,
        feature: str,
        scheme: str,
        bucket: str,
        g: pd.DataFrame,
    ) -> None:
        n = int(len(g))
        if n <= 0:
            return
        mae = pd.to_numeric(g.get("trade_mae_atr", pd.Series(index=g.index)), errors="coerce")
        mfe = pd.to_numeric(g.get("trade_mfe_atr", pd.Series(index=g.index)), errors="coerce")
        m_mae = mae.notna()
        m_mfe = mfe.notna()
        mae_mean = float(mae[m_mae].mean()) if bool(m_mae.any()) else float("nan")
        mfe_mean = float(mfe[m_mfe].mean()) if bool(m_mfe.any()) else float("nan")
        mae_p90 = float(mae[m_mae].quantile(0.90)) if bool(m_mae.any()) else float("nan")
        mfe_p90 = float(mfe[m_mfe].quantile(0.90)) if bool(m_mfe.any()) else float("nan")
        rows.append(
            {
                "symbol": symbol,
                "split": split,
                "profile": profile,
                "feature": feature,
                "scheme": scheme,
                "bucket": bucket,
                "n_trades": float(n),
                "win_rate": float(pd.to_numeric(g["win"], errors="coerce").mean()),
                "avg_pnl": float(pd.to_numeric(g["trade_pnl"], errors="coerce").mean()),
                "stop_loss_rate": float(pd.to_numeric(g["stop_loss_any"], errors="coerce").mean()),
                "tp2_rate": float(pd.to_numeric(g["tp2_any"], errors="coerce").mean()),
                "hold_hours_median": float(pd.to_numeric(g["hold_hours"], errors="coerce").median()),
                "mae_atr_mean": mae_mean,
                "mae_atr_p90": mae_p90,
                "mfe_atr_mean": mfe_mean,
                "mfe_atr_p90": mfe_p90,
                "mae_cov": float(m_mae.mean()) if n else float("nan"),
            }
        )

    out_stats = out_dir / f"b30_mae_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b30_mae_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b30_mae_coverage_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        try:
            df = pd.read_csv(
                trades_csv,
                dtype=str,
                encoding="utf-8-sig",
                usecols=lambda c: c
                in {
                    "entry_time",
                    "side",
                    "entry",
                    "signal",
                    "exit_time",
                    "pnl",
                    "reason",
                    *need_cols,
                },
            )
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if df.empty or "entry_time" not in df.columns:
            continue

        for c in ["signal", "reason", "side", "entry", "exit_time", "pnl"]:
            if c not in df.columns:
                df[c] = ""
        for c in need_cols:
            if c not in df.columns:
                df[c] = ""
        df = df.fillna("").astype(str)

        key_cols = ["entry_time", "side", "entry"]
        is_entry = df["signal"].astype(str).str.strip().ne("")
        entry_rows = df[is_entry].drop_duplicates(subset=key_cols, keep="last").copy()
        if entry_rows.empty:
            continue

        pnl = pd.to_numeric(df["pnl"], errors="coerce")
        pnl0 = pnl.fillna(0.0)
        reason_s = df["reason"].astype(str).str.strip()
        is_tp2 = reason_s.isin(["tp_cam_r2", "tp_cam_s2"])
        is_stop = reason_s.str.contains("stop", case=False, na=False)
        is_stop_loss = is_stop & (pnl0 < 0.0)

        entry_dt = pd.to_datetime(df["entry_time"], utc=True, errors="coerce")
        exit_dt = pd.to_datetime(df["exit_time"], utc=True, errors="coerce")

        pnl_sum = pnl.groupby([df[k] for k in key_cols], sort=False).sum(min_count=1)
        tp2_any = is_tp2.groupby([df[k] for k in key_cols], sort=False).any()
        stop_loss_any = is_stop_loss.groupby([df[k] for k in key_cols], sort=False).any()
        max_exit = exit_dt.groupby([df[k] for k in key_cols], sort=False).max()
        min_entry = entry_dt.groupby([df[k] for k in key_cols], sort=False).min()

        tl = pd.DataFrame(
            {
                "entry_time": pnl_sum.index.get_level_values(0).astype(str),
                "side": pnl_sum.index.get_level_values(1).astype(str),
                "entry": pnl_sum.index.get_level_values(2).astype(str),
                "trade_pnl": pnl_sum.to_numpy(),
                "tp2_any": tp2_any.to_numpy(dtype=bool),
                "stop_loss_any": stop_loss_any.to_numpy(dtype=bool),
                "max_exit_time": max_exit.to_numpy(),
                "min_entry_time": min_entry.to_numpy(),
            }
        ).copy()
        tl["win"] = pd.to_numeric(tl["trade_pnl"], errors="coerce").fillna(0.0) > 0.0
        hold = pd.to_datetime(tl["max_exit_time"], utc=True, errors="coerce") - pd.to_datetime(tl["min_entry_time"], utc=True, errors="coerce")
        tl["hold_hours"] = hold.dt.total_seconds() / 3600.0

        feats = entry_rows[key_cols + [c for c in need_cols if c in entry_rows.columns]].copy()
        merged = tl.merge(feats, on=key_cols, how="left")
        if merged.empty:
            continue

        csv_path: Optional[Path]
        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None

        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "symbol": sym_u,
                    "split": str(split).strip(),
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        ohlc = load_ohlcv_1h(csv_path, tz=None)
        if ohlc.empty or "high" not in ohlc.columns or "low" not in ohlc.columns:
            cov_rows.append(
                {
                    "symbol": sym_u,
                    "split": str(split).strip(),
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")
        low_arr = pd.to_numeric(ohlc["low"], errors="coerce").to_numpy(dtype=float)
        high_arr = pd.to_numeric(ohlc["high"], errors="coerce").to_numpy(dtype=float)

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        hold_td = pd.to_timedelta(pd.to_numeric(merged.get("hold_hours", pd.Series(index=merged.index)), errors="coerce"), unit="h")
        exit_dt = entry_dt + hold_td
        entry_ns = entry_dt.astype("int64")
        exit_ns = exit_dt.astype("int64")
        entry_px = pd.to_numeric(merged["entry"], errors="coerce")
        atr0 = pd.to_numeric(merged.get("atr", pd.Series(index=merged.index)), errors="coerce")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        mae_atr: List[float] = []
        mfe_atr: List[float] = []
        priced = 0
        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            ex = exit_ns.iloc[i]
            ep = entry_px.iloc[i]
            a0 = atr0.iloc[i]
            if pd.isna(en) or pd.isna(ex) or pd.isna(ep) or pd.isna(a0) or float(a0) <= 0.0:
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                continue
            si = int(np.searchsorted(ts_ns, int(en), side="left"))
            ei = int(np.searchsorted(ts_ns, int(ex), side="right"))
            if si < 0:
                si = 0
            if ei > int(len(ts_ns)):
                ei = int(len(ts_ns))
            if not (0 <= si < ei <= int(len(ts_ns))):
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                continue
            lo = float(np.nanmin(low_arr[si:ei]))
            hi = float(np.nanmax(high_arr[si:ei]))
            if not (np.isfinite(lo) and np.isfinite(hi)):
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                continue
            s0 = side_s.iloc[i]
            if s0 == "SHORT":
                mae = (hi - float(ep)) / float(a0)
                mfe = (float(ep) - lo) / float(a0)
            else:
                mae = (float(ep) - lo) / float(a0)
                mfe = (hi - float(ep)) / float(a0)
            mae_atr.append(float(mae))
            mfe_atr.append(float(mfe))
            priced += 1

        merged = merged.copy()
        merged["trade_mae_atr"] = mae_atr
        merged["trade_mfe_atr"] = mfe_atr

        cov_rows.append(
            {
                "symbol": sym_u,
                "split": str(split).strip(),
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(priced),
                "priced_pct": float(priced) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        for feat in features:
            if feat not in merged.columns:
                continue
            x_num = pd.to_numeric(merged[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dfm = merged[m].copy()
            dfm["_x"] = x_num[m].astype(float).to_numpy()
            q_eff = 10 if feat == "sv_atr_ratio_1h" else 4
            uniq = float(dfm["_x"].nunique())
            if q_eff == 10 and (int(len(dfm)) < 50 or uniq < 10.0):
                q_eff = 4
            if int(len(dfm)) < 20 or uniq < 4.0:
                continue
            try:
                cat = pd.qcut(dfm["_x"], q=q_eff, duplicates="drop")
            except Exception:
                continue
            q_actual = int(getattr(cat, "cat").categories.size)
            dfm["_bucket_id"] = (cat.cat.codes.astype(int) + 1).map(lambda z: f"q{q_actual}_bin{int(z)}")
            scheme = "deciles10" if q_eff == 10 else "qtiles4"
            for b, g in dfm.groupby("_bucket_id", sort=True):
                _add_row(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme=scheme,
                    bucket=str(b),
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_stats, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], observed=True):
            sub2 = sub.copy()
            sub2["avg_pnl"] = pd.to_numeric(sub2["avg_pnl"], errors="coerce")
            sub2["mae_atr_mean"] = pd.to_numeric(sub2["mae_atr_mean"], errors="coerce")
            sub2["n_trades"] = pd.to_numeric(sub2["n_trades"], errors="coerce").fillna(0.0)
            sub2 = sub2[sub2["avg_pnl"].notna() & (sub2["n_trades"] > 0)].copy()
            if sub2.empty:
                continue
            sub2["_bin"] = sub2["bucket"].astype(str).str.extract(r"bin(\d+)$")[0]
            sub2["_bin"] = pd.to_numeric(sub2["_bin"], errors="coerce")
            sub2 = sub2[sub2["_bin"].notna()].copy()
            if sub2.empty:
                continue
            lo = sub2.loc[sub2["_bin"].idxmin()]
            hi = sub2.loc[sub2["_bin"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(sub2["n_trades"].sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                    "top_minus_bot_mae_atr_mean": float(
                        pd.to_numeric(hi["mae_atr_mean"], errors="coerce") - pd.to_numeric(lo["mae_atr_mean"], errors="coerce")
                    ),
                }
            )
    pd.DataFrame(summ_rows).to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_stats, "SUMMARY": out_sum, "COVERAGE": out_cov}


def run_b60_evidence(
    *,
    p0_sweep_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    q: Optional[int] = None,
    date_tag: str,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    b60_features = [
        "k",
        "N",
        "M",
        "X",
        "body_k",
        "touch_k",
        "shadow_k",
        "stop_k",
        "risk_per_trade",
        "sv_swing_high_4h",
        "sv_swing_low_4h",
        "sv_risk_on_mkt",
        "sv_use_struct_vote",
    ]
    derived_features = ["sv_swing_present_4h"]

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")

    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, b60_features)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        if "sv_swing_present_4h" not in merged.columns:
            swing_high = pd.to_numeric(merged.get("sv_swing_high_4h", pd.Series(np.nan, index=merged.index)), errors="coerce")
            swing_low = pd.to_numeric(merged.get("sv_swing_low_4h", pd.Series(np.nan, index=merged.index)), errors="coerce")
            present = (swing_high.notna() | swing_low.notna()).astype(float)
            if float(present.nunique()) > 1.0:
                merged["sv_swing_present_4h"] = present

        features_to_eval = b60_features + derived_features

        for feat in features_to_eval:
            if feat not in merged.columns:
                continue
            x_raw = merged[feat].astype(str)
            x_num = pd.to_numeric(x_raw, errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                xs = x_raw.astype(str).str.strip().str.lower()
                ok = xs.isin(["true", "false", "1", "0"])
                if int(ok.sum()) >= 20:
                    x_num = xs.map({"true": 1.0, "false": 0.0, "1": 1.0, "0": 0.0})
                    m = x_num.notna()
            if int(m.sum()) < 20:
                continue

            dfm = merged[m].copy()
            dfm["_x"] = x_num[m].astype(float).to_numpy()

            uniq = float(dfm["_x"].nunique())
            if uniq <= 1.0:
                continue

            if uniq <= 2.0 and _is_int_like_series(dfm["_x"]):
                for v, g in dfm.groupby("_x", sort=True):
                    _add_bucket_rows(
                        bucket_rows,
                        symbol=sym_u,
                        split=str(split).strip(),
                        profile=str(profile).strip(),
                        feature=feat,
                        scheme="code",
                        bucket_id=f"code={int(round(float(v)))}",
                        bucket_range="",
                        g=g,
                    )
                continue

            q_eff: int
            if q is not None:
                q_eff = int(q)
            else:
                q_eff = 10 if feat in {"risk_per_trade", "stop_k"} else 4
            if q_eff == 10 and (int(len(dfm)) < 50 or uniq < 10.0):
                q_eff = 4
            if int(len(dfm)) < 20 or uniq < 4.0:
                continue

            try:
                cat = pd.qcut(dfm["_x"], q=q_eff, duplicates="drop")
            except Exception:
                continue
            q_actual = int(getattr(cat, "cat").categories.size)
            dfm["_bucket_id"] = (cat.cat.codes.astype(int) + 1).map(lambda z: f"q{q_actual}_bin{int(z)}")
            dfm["_bucket_range"] = cat.astype(str)
            scheme = "deciles10" if q_eff == 10 else "qtiles4"
            for b, g in dfm.groupby("_bucket_id", sort=True):
                br = str(g["_bucket_range"].iloc[0]) if "_bucket_range" in g.columns and int(len(g)) > 0 else ""
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme=scheme,
                    bucket_id=str(b),
                    bucket_range=br,
                    g=g,
                )

    buckets_df = pd.DataFrame(bucket_rows)
    buckets_df.insert(0, "scope", scope_id) if not buckets_df.empty else None
    out_csv = out_dir / f"b60_bucket_stats_{date_tag}_v1.csv"
    summary_csv = out_dir / f"b60_feature_summary_{date_tag}_v1.csv"

    if buckets_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "symbol",
                "split",
                "profile",
                "feature",
                "scheme",
                "bucket",
                "n_trades",
                "win_rate",
                "avg_pnl",
                "stop_loss_rate",
                "tp2_rate",
                "hold_hours_median",
            ]
        ).to_csv(out_csv, index=False, encoding="utf-8-sig")
        pd.DataFrame(columns=["scope", "feature", "scheme", "n_trades", "top_minus_bot_avg_pnl", "notes"]).to_csv(
            summary_csv, index=False, encoding="utf-8-sig"
        )
        return {"BUCKETS": out_csv, "SUMMARY": summary_csv}

    buckets_df.to_csv(out_csv, index=False, encoding="utf-8-sig")

    summ_rows: List[Dict[str, object]] = []
    for (feat, scheme), sub in buckets_df.groupby(["feature", "scheme"], observed=True):
        sub2 = sub.copy()
        sub2["avg_pnl"] = pd.to_numeric(sub2["avg_pnl"], errors="coerce")
        sub2["n_trades"] = pd.to_numeric(sub2["n_trades"], errors="coerce").fillna(0.0)
        sub2 = sub2[sub2["avg_pnl"].notna() & (sub2["n_trades"] > 0)].copy()
        if sub2.empty:
            continue
        top = sub2.sort_values(["avg_pnl"], ascending=False, kind="mergesort").head(1)
        bot = sub2.sort_values(["avg_pnl"], ascending=True, kind="mergesort").head(1)
        top_p = float(top["avg_pnl"].iloc[0])
        bot_p = float(bot["avg_pnl"].iloc[0])
        summ_rows.append(
            {
                "scope": scope_id,
                "feature": feat,
                "scheme": scheme,
                "n_trades": float(sub2["n_trades"].sum()),
                "top_minus_bot_avg_pnl": float(top_p - bot_p),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(summary_csv, index=False, encoding="utf-8-sig")

    return {"BUCKETS": out_csv, "SUMMARY": summary_csv}


def run_b60_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b60_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b60_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _bin_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"bin(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        sub2 = sub.copy()
        if scheme in {"deciles10", "qtiles4"}:
            sub2["_bin"] = sub2["bucket"].map(_bin_idx)
            sub2 = sub2[sub2["_bin"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_bin"] = sub2["_bin"].astype(int)
            lo = sub2.loc[sub2["_bin"].idxmin()]
            hi = sub2.loc[sub2["_bin"].idxmax()]
            if float(lo["n_trades"]) <= 0.0 or float(hi["n_trades"]) <= 0.0:
                continue
            sufficient = bool(float(lo["n_trades"]) >= min_n and float(hi["n_trades"]) >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": str(lo["bucket"]),
                    "group_b": str(hi["bucket"]),
                    "n_a": float(lo["n_trades"]),
                    "n_b": float(hi["n_trades"]),
                    "avg_pnl_a": float(lo["avg_pnl"]),
                    "avg_pnl_b": float(hi["avg_pnl"]),
                    "stop_loss_rate_a": float(lo["stop_loss_rate"]),
                    "stop_loss_rate_b": float(hi["stop_loss_rate"]),
                    "win_rate_a": float(lo["win_rate"]),
                    "win_rate_b": float(hi["win_rate"]),
                    "tp2_rate_a": float(lo["tp2_rate"]),
                    "tp2_rate_b": float(hi["tp2_rate"]),
                    "delta_avg_pnl": float(hi["avg_pnl"] - lo["avg_pnl"]),
                    "delta_stop_loss_rate": float(hi["stop_loss_rate"] - lo["stop_loss_rate"]),
                    "delta_win_rate": float(hi["win_rate"] - lo["win_rate"]),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )
            continue

        if scheme == "code":
            a = sub2[sub2["bucket"].astype(str).eq("code=0")].copy()
            b = sub2[sub2["bucket"].astype(str).eq("code=1")].copy()
            if a.empty or b.empty:
                continue
            aa = _agg_rows(a)
            bb = _agg_rows(b)
            sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code=0",
                    "group_b": "code=1",
                    "n_a": aa["n"],
                    "n_b": bb["n"],
                    "avg_pnl_a": aa["avg_pnl"],
                    "avg_pnl_b": bb["avg_pnl"],
                    "stop_loss_rate_a": aa["stop_loss_rate"],
                    "stop_loss_rate_b": bb["stop_loss_rate"],
                    "win_rate_a": aa["win_rate"],
                    "win_rate_b": bb["win_rate"],
                    "tp2_rate_a": aa["tp2_rate"],
                    "tp2_rate_b": bb["tp2_rate"],
                    "delta_avg_pnl": float(bb["avg_pnl"] - aa["avg_pnl"]),
                    "delta_stop_loss_rate": float(bb["stop_loss_rate"] - aa["stop_loss_rate"]),
                    "delta_win_rate": float(bb["win_rate"] - aa["win_rate"]),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )
            continue

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    summ_rows: List[Dict[str, object]] = []
    if not pairs_df.empty:
        for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], sort=True):
            g2 = g[pd.to_numeric(g["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)].copy()
            if g2.empty:
                summ_rows.append(
                    {
                        "scope": scope_id,
                        "split": split_id,
                        "feature": str(feat),
                        "scheme": str(scheme),
                        "n_pairs": float(len(g)),
                        "n_sufficient": 0.0,
                        "frac_pnl_better": float("nan"),
                        "frac_stop_loss_better": float("nan"),
                        "frac_both": float("nan"),
                        "notes": "no sufficient pairs",
                    }
                )
                continue
            pnl_better = pd.to_numeric(g2["delta_avg_pnl"], errors="coerce") > 0.0
            sl_better = pd.to_numeric(g2["delta_stop_loss_rate"], errors="coerce") < 0.0
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": float(len(g2)),
                    "frac_pnl_better": float(pnl_better.mean()),
                    "frac_stop_loss_better": float(sl_better.mean()),
                    "frac_both": float((pnl_better & sl_better).mean()),
                    "notes": "",
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b60_swing_present_interactions(
    *,
    p0_sweep_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 50.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    cols = [
        "sv_risk_on_mkt",
        "sv_regime_code",
        "sv_swing_high_4h",
        "sv_swing_low_4h",
    ]

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    def _bool01(s: pd.Series) -> pd.Series:
        xs = s.fillna("").astype(str).str.strip().str.lower()
        return xs.map({"true": 1, "false": 0, "1": 1, "0": 0})

    out_pairs = out_dir / f"b60_swing_present_interaction_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b60_swing_present_interaction_summary_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        merged = merged.dropna(subset=["trade_pnl"]).copy()
        if merged.empty:
            continue

        prof_id = "A_all" if profile_merge else str(profile).strip()

        risk01 = _bool01(merged.get("sv_risk_on_mkt", pd.Series(index=merged.index)))
        risk_grp = pd.Series(["na"] * int(len(merged)), index=merged.index, dtype=str)
        risk_grp.loc[risk01.notna()] = np.where(risk01.loc[risk01.notna()].astype(int).eq(1), "risk=1", "risk=0")

        regime = pd.to_numeric(merged.get("sv_regime_code", pd.Series(index=merged.index)), errors="coerce")
        regime_grp = pd.Series(["na"] * int(len(merged)), index=merged.index, dtype=str)
        regime_grp.loc[regime.notna()] = np.where(regime.loc[regime.notna()].round().astype(int).eq(0), "regime=0", "regime!=0")

        swing_high = pd.to_numeric(merged.get("sv_swing_high_4h", pd.Series(index=merged.index)), errors="coerce")
        swing_low = pd.to_numeric(merged.get("sv_swing_low_4h", pd.Series(index=merged.index)), errors="coerce")
        swing_present = (swing_high.notna() | swing_low.notna()).astype(int)

        df0 = merged.copy()
        df0["risk_grp"] = risk_grp.astype(str)
        df0["regime_grp"] = regime_grp.astype(str)
        df0["swing_present"] = swing_present.astype(int)

        for (rg, eg), sub in df0.groupby(["risk_grp", "regime_grp"], dropna=False, sort=False):
            a = sub[sub["swing_present"].astype(int).eq(0)].copy()
            b = sub[sub["swing_present"].astype(int).eq(1)].copy()
            if a.empty or b.empty:
                continue

            a["trade_pnl"] = pd.to_numeric(a["trade_pnl"], errors="coerce")
            b["trade_pnl"] = pd.to_numeric(b["trade_pnl"], errors="coerce")
            a = a.dropna(subset=["trade_pnl"])
            b = b.dropna(subset=["trade_pnl"])
            if a.empty or b.empty:
                continue

            for c in ["win", "stop_loss_any", "tp2_any"]:
                if c in a.columns:
                    a[c] = pd.to_numeric(a[c], errors="coerce")
                if c in b.columns:
                    b[c] = pd.to_numeric(b[c], errors="coerce")

            n_a = float(len(a))
            n_b = float(len(b))
            sufficient = bool(n_a >= min_n and n_b >= min_n)

            avg_a = float(a["trade_pnl"].mean())
            avg_b = float(b["trade_pnl"].mean())
            sl_a = float(a["stop_loss_any"].mean()) if "stop_loss_any" in a.columns else float("nan")
            sl_b = float(b["stop_loss_any"].mean()) if "stop_loss_any" in b.columns else float("nan")
            win_a = float(a["win"].mean()) if "win" in a.columns else float("nan")
            win_b = float(b["win"].mean()) if "win" in b.columns else float("nan")
            tp2_a = float(a["tp2_any"].mean()) if "tp2_any" in a.columns else float("nan")
            tp2_b = float(b["tp2_any"].mean()) if "tp2_any" in b.columns else float("nan")

            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof_id,
                    "risk_grp": str(rg),
                    "regime_grp": str(eg),
                    "group_a": "swing_present=0",
                    "group_b": "swing_present=1",
                    "n_a": n_a,
                    "n_b": n_b,
                    "avg_pnl_a": avg_a,
                    "avg_pnl_b": avg_b,
                    "stop_loss_rate_a": sl_a,
                    "stop_loss_rate_b": sl_b,
                    "win_rate_a": win_a,
                    "win_rate_b": win_b,
                    "tp2_rate_a": tp2_a,
                    "tp2_rate_b": tp2_b,
                    "delta_avg_pnl": float(avg_b - avg_a),
                    "delta_stop_loss_rate": float(sl_b - sl_a),
                    "delta_win_rate": float(win_b - win_a),
                    "sufficient": int(sufficient),
                    "notes": "",
                }
            )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "risk_grp",
                "regime_grp",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (rg, eg), g in pairs_df.groupby(["risk_grp", "regime_grp"], dropna=False, sort=False):
        gg = g.copy()
        m = suff.loc[gg.index]
        gg2 = gg[m].copy()
        if gg2.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "risk_grp": str(rg),
                    "regime_grp": str(eg),
                    "n_pairs": float(len(gg)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg2["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg2["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "risk_grp": str(rg),
                "regime_grp": str(eg),
                "n_pairs": float(len(gg)),
                "n_sufficient": float(len(gg2)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )

    all_suff = pairs_df[suff].copy()
    if not all_suff.empty:
        pnl_better = pd.to_numeric(all_suff["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(all_suff["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "risk_grp": "ALL",
                "regime_grp": "ALL",
                "n_pairs": float(len(pairs_df)),
                "n_sufficient": float(len(all_suff)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "overall(sufficient_only)",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b55_candle_patterns_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b55_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b55_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b55_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b55_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        o = pd.to_numeric(ohlc["open"], errors="coerce").astype(float)
        h = pd.to_numeric(ohlc["high"], errors="coerce").astype(float)
        l = pd.to_numeric(ohlc["low"], errors="coerce").astype(float)
        c = pd.to_numeric(ohlc["close"], errors="coerce").astype(float)

        rng = (h - l).astype(float)
        rng_eff = rng.where(rng > 0.0, np.nan)
        body = (c - o).abs().astype(float)

        body_lo = np.minimum(o.to_numpy(dtype=float), c.to_numpy(dtype=float))
        body_hi = np.maximum(o.to_numpy(dtype=float), c.to_numpy(dtype=float))

        prev_o = o.shift(1)
        prev_c = c.shift(1)
        prev_h = h.shift(1)
        prev_l = l.shift(1)
        prev_body_lo = np.minimum(prev_o.to_numpy(dtype=float), prev_c.to_numpy(dtype=float))
        prev_body_hi = np.maximum(prev_o.to_numpy(dtype=float), prev_c.to_numpy(dtype=float))
        prev_body = (prev_c - prev_o).abs().astype(float)
        prev_body_eff = prev_body.where(prev_body > 0.0, np.nan)

        bull_base = (prev_c < prev_o) & (c > o)
        bear_base = (prev_c > prev_o) & (c < o)

        inside_len = np.maximum(0.0, np.minimum(prev_body_hi, body_hi) - np.maximum(prev_body_lo, body_lo))
        cover_ratio = inside_len / (prev_body_eff.to_numpy(dtype=float) + eps)
        full_bull = bull_base & (body_lo <= prev_body_lo) & (body_hi >= prev_body_hi)
        full_bear = bear_base & (body_hi >= prev_body_hi) & (body_lo <= prev_body_lo)
        partial_bull = bull_base & (~full_bull) & np.isfinite(cover_ratio) & (cover_ratio >= 0.70)
        partial_bear = bear_base & (~full_bear) & np.isfinite(cover_ratio) & (cover_ratio >= 0.70)

        shadow_bull = bull_base & (h >= prev_h) & (l <= prev_l)
        shadow_bear = bear_base & (h >= prev_h) & (l <= prev_l)

        bull_score = (
            (partial_bull | full_bull | shadow_bull).astype(int)
            + full_bull.astype(int)
            + shadow_bull.astype(int)
        ).astype(int)
        bear_score = (
            (partial_bear | full_bear | shadow_bear).astype(int)
            + full_bear.astype(int)
            + shadow_bear.astype(int)
        ).astype(int)
        bull_score = bull_score.clip(0, 3)
        bear_score = bear_score.clip(0, 3)

        upper = (h - np.maximum(o, c)).astype(float)
        lower = (np.minimum(o, c) - l).astype(float)
        body_ratio = (body / (rng_eff + eps)).astype(float)
        close_pos = ((c - l) / (rng_eff + eps)).astype(float)

        hammer_base = (body_ratio <= 0.30) & (lower >= (2.0 * body)) & ((upper / (rng_eff + eps)) <= 0.15)
        star_base = (body_ratio <= 0.30) & (upper >= (2.0 * body)) & ((lower / (rng_eff + eps)) <= 0.15)

        hammer_score = (
            hammer_base.astype(int)
            + (hammer_base & (lower >= (3.0 * body))).astype(int)
            + (hammer_base & (close_pos >= 0.70)).astype(int)
        ).astype(int)
        star_score = (
            star_base.astype(int)
            + (star_base & (upper >= (3.0 * body))).astype(int)
            + (star_base & (close_pos <= 0.30)).astype(int)
        ).astype(int)
        hammer_score = hammer_score.clip(0, 3)
        star_score = star_score.clip(0, 3)

        return pd.DataFrame(
            {
                "bull_engulf_score": bull_score.astype(int),
                "bear_engulf_score": bear_score.astype(int),
                "bull_pinbar_score": hammer_score.astype(int),
                "bear_pinbar_score": star_score.astype(int),
            },
            index=ohlc.index,
        )

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        engulf_vals: List[float] = []
        pin_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                engulf_vals.append(float("nan"))
                pin_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                engulf_vals.append(float("nan"))
                pin_vals.append(float("nan"))
                continue

            if side_s.iloc[i] == "SHORT":
                e0 = float(feats["bear_engulf_score"].iloc[j])
                p0 = float(feats["bear_pinbar_score"].iloc[j])
            else:
                e0 = float(feats["bull_engulf_score"].iloc[j])
                p0 = float(feats["bull_pinbar_score"].iloc[j])

            if not (np.isfinite(e0) and np.isfinite(p0)):
                engulf_vals.append(float("nan"))
                pin_vals.append(float("nan"))
                continue
            engulf_vals.append(e0)
            pin_vals.append(p0)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["px_cdl_engulf_score_1h"] = engulf_vals
        dfm["px_cdl_engulf_flag_1h"] = (pd.to_numeric(dfm["px_cdl_engulf_score_1h"], errors="coerce") >= 2.0).astype(int)
        dfm["px_cdl_pinbar_score_1h"] = pin_vals
        dfm["px_cdl_pinbar_flag_1h"] = (pd.to_numeric(dfm["px_cdl_pinbar_score_1h"], errors="coerce") >= 2.0).astype(int)

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "px_cdl_engulf_score_1h",
                    "px_cdl_engulf_flag_1h",
                    "px_cdl_pinbar_score_1h",
                    "px_cdl_pinbar_flag_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in [
            "px_cdl_engulf_score_1h",
            "px_cdl_engulf_flag_1h",
            "px_cdl_pinbar_score_1h",
            "px_cdl_pinbar_flag_1h",
        ]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "px_cdl_engulf_score_1h",
            "px_cdl_engulf_flag_1h",
            "px_cdl_pinbar_score_1h",
            "px_cdl_pinbar_flag_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in [
            "px_cdl_engulf_score_1h",
            "px_cdl_engulf_flag_1h",
            "px_cdl_pinbar_score_1h",
            "px_cdl_pinbar_flag_1h",
        ]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b55_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b55_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b55_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue
        max_code = int(sub2["_code"].max())
        if max_code >= 2 and str(feat).endswith("_score_1h"):
            a = sub2[sub2["_code"] <= 0].copy()
            b = sub2[sub2["_code"] >= 1].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4=0",
                    "group_b": "code4>=1",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_0_vs_ge1",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b56_fib_retrace_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    lookback_bars: int = 240,
    near_k_atr: float = 0.20,
    min_range_height_atr: float = 1.0,
    max_range_height_atr: float = 12.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b56_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b56_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b56_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b56_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    lookback_bars = int(lookback_bars)
    near_k_atr = float(near_k_atr)
    min_range_height_atr = float(min_range_height_atr)
    max_range_height_atr = float(max_range_height_atr)

    fib_levels = np.array([0.236, 0.382, 0.50, 0.618, 0.786], dtype=float)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        h = pd.to_numeric(ohlc["high"], errors="coerce").astype(float)
        l = pd.to_numeric(ohlc["low"], errors="coerce").astype(float)
        c = pd.to_numeric(ohlc["close"], errors="coerce").astype(float)

        prev_c = c.shift(1)
        tr = pd.concat([(h - l).abs(), (h - prev_c).abs(), (l - prev_c).abs()], axis=1).max(axis=1)
        atr = tr.ewm(span=14, adjust=False).mean()
        atr_eff = atr.where(atr > 0.0, np.nan)

        roll_high = h.rolling(lookback_bars, min_periods=max(20, lookback_bars // 6)).max().shift(1)
        roll_low = l.rolling(lookback_bars, min_periods=max(20, lookback_bars // 6)).min().shift(1)
        height = (roll_high - roll_low).astype(float)
        height_eff = height.where(height > 0.0, np.nan)
        height_atr = (height_eff / (atr_eff + eps)).astype(float)
        range_ok = height_atr.notna() & (height_atr >= min_range_height_atr) & (height_atr <= max_range_height_atr)

        depth_long = ((roll_high - c) / (height_eff + eps)).astype(float).clip(0.0, 1.0)
        depth_short = ((c - roll_low) / (height_eff + eps)).astype(float).clip(0.0, 1.0)

        bucket_long = np.select(
            [
                depth_long < 0.236,
                depth_long < 0.382,
                depth_long < 0.50,
                depth_long < 0.618,
                depth_long < 0.786,
            ],
            [0, 1, 2, 3, 4],
            default=5,
        ).astype(int)
        bucket_short = np.select(
            [
                depth_short < 0.236,
                depth_short < 0.382,
                depth_short < 0.50,
                depth_short < 0.618,
                depth_short < 0.786,
            ],
            [0, 1, 2, 3, 4],
            default=5,
        ).astype(int)

        lev_long = roll_high.to_numpy(dtype=float)[:, None] - height_eff.to_numpy(dtype=float)[:, None] * fib_levels[None, :]
        lev_short = roll_low.to_numpy(dtype=float)[:, None] + height_eff.to_numpy(dtype=float)[:, None] * fib_levels[None, :]
        c_arr = c.to_numpy(dtype=float)[:, None]
        atr_arr = atr_eff.to_numpy(dtype=float)
        atr_mat = atr_arr[:, None]

        dist_long = np.abs(c_arr - lev_long) / (atr_mat + eps)
        dist_short = np.abs(c_arr - lev_short) / (atr_mat + eps)

        min_idx_long = np.argmin(dist_long, axis=1).astype(int)
        min_idx_short = np.argmin(dist_short, axis=1).astype(int)
        min_dist_long = dist_long[np.arange(dist_long.shape[0]), min_idx_long]
        min_dist_short = dist_short[np.arange(dist_short.shape[0]), min_idx_short]

        near_flag_long = (min_dist_long <= near_k_atr).astype(int)
        near_flag_short = (min_dist_short <= near_k_atr).astype(int)
        near_score_long = ((min_idx_long + 1) * near_flag_long).astype(int)
        near_score_short = ((min_idx_short + 1) * near_flag_short).astype(int)

        depth_long = depth_long.where(range_ok)
        depth_short = depth_short.where(range_ok)

        out = pd.DataFrame(
            {
                "fib_depth_long": depth_long.astype(float),
                "fib_depth_short": depth_short.astype(float),
                "fib_bucket_long": pd.Series(bucket_long, index=ohlc.index).astype(int),
                "fib_bucket_short": pd.Series(bucket_short, index=ohlc.index).astype(int),
                "fib_near_flag_long": pd.Series(near_flag_long, index=ohlc.index).astype(int),
                "fib_near_flag_short": pd.Series(near_flag_short, index=ohlc.index).astype(int),
                "fib_near_score_long": pd.Series(near_score_long, index=ohlc.index).astype(int),
                "fib_near_score_short": pd.Series(near_score_short, index=ohlc.index).astype(int),
                "fib_height_atr": height_atr.astype(float),
            },
            index=ohlc.index,
        )
        return out

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        depth_bucket_vals: List[float] = []
        near_flag_vals: List[float] = []
        near_score_vals: List[float] = []
        depth_vals: List[float] = []
        height_atr_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                depth_bucket_vals.append(float("nan"))
                near_flag_vals.append(float("nan"))
                near_score_vals.append(float("nan"))
                depth_vals.append(float("nan"))
                height_atr_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                depth_bucket_vals.append(float("nan"))
                near_flag_vals.append(float("nan"))
                near_score_vals.append(float("nan"))
                depth_vals.append(float("nan"))
                height_atr_vals.append(float("nan"))
                continue

            if side_s.iloc[i] == "SHORT":
                b0 = float(feats["fib_bucket_short"].iloc[j])
                f0 = float(feats["fib_near_flag_short"].iloc[j])
                s0 = float(feats["fib_near_score_short"].iloc[j])
                d0 = float(feats["fib_depth_short"].iloc[j])
            else:
                b0 = float(feats["fib_bucket_long"].iloc[j])
                f0 = float(feats["fib_near_flag_long"].iloc[j])
                s0 = float(feats["fib_near_score_long"].iloc[j])
                d0 = float(feats["fib_depth_long"].iloc[j])
            ha = float(feats["fib_height_atr"].iloc[j])

            if not (np.isfinite(b0) and np.isfinite(f0) and np.isfinite(s0)):
                depth_bucket_vals.append(float("nan"))
                near_flag_vals.append(float("nan"))
                near_score_vals.append(float("nan"))
                depth_vals.append(float("nan"))
                height_atr_vals.append(float("nan"))
                continue
            depth_bucket_vals.append(b0)
            near_flag_vals.append(f0)
            near_score_vals.append(s0)
            depth_vals.append(d0)
            height_atr_vals.append(ha)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["fib_retrace_bucket_1h"] = depth_bucket_vals
        dfm["fib_retrace_near_flag_1h"] = near_flag_vals
        dfm["fib_retrace_near_score_1h"] = near_score_vals
        dfm["fib_retrace_depth_1h"] = depth_vals
        dfm["fib_retrace_height_atr_1h"] = height_atr_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "fib_retrace_bucket_1h",
                    "fib_retrace_near_flag_1h",
                    "fib_retrace_near_score_1h",
                    "fib_retrace_depth_1h",
                    "fib_retrace_height_atr_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in [
            "fib_retrace_bucket_1h",
            "fib_retrace_near_flag_1h",
            "fib_retrace_near_score_1h",
        ]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "fib_retrace_bucket_1h",
            "fib_retrace_near_flag_1h",
            "fib_retrace_near_score_1h",
            "fib_retrace_depth_1h",
            "fib_retrace_height_atr_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["fib_retrace_bucket_1h", "fib_retrace_near_flag_1h", "fib_retrace_near_score_1h", "fib_retrace_depth_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr", "fib_retrace_height_atr_1h"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b56_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b56_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b56_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue
        max_code = int(sub2["_code"].max())
        if max_code >= 2 and str(feat).endswith("_score_1h"):
            a = sub2[sub2["_code"] <= 0].copy()
            b = sub2[sub2["_code"] >= 1].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4=0",
                    "group_b": "code4>=1",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_0_vs_ge1",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b114_tk_tp3_extension_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    lookback_bars: int = 96,
    deep_ratio: float = 0.786,
    min_range_height_atr: float = 1.0,
    max_range_height_atr: float = 12.0,
    wick_ratio_min: float = 0.25,
    close_pos_min: float = 0.45,
    body_ratio_min: float = 0.30,
    strong_close_pos_min: float = 0.60,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b114_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b114_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b114_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b114_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    lookback_bars = int(lookback_bars)
    deep_ratio = float(deep_ratio)
    min_range_height_atr = float(min_range_height_atr)
    max_range_height_atr = float(max_range_height_atr)
    wick_ratio_min = float(wick_ratio_min)
    close_pos_min = float(close_pos_min)
    body_ratio_min = float(body_ratio_min)
    strong_close_pos_min = float(strong_close_pos_min)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        o = pd.to_numeric(ohlc["open"], errors="coerce").astype(float)
        h = pd.to_numeric(ohlc["high"], errors="coerce").astype(float)
        l = pd.to_numeric(ohlc["low"], errors="coerce").astype(float)
        c = pd.to_numeric(ohlc["close"], errors="coerce").astype(float)

        prev_c = c.shift(1)
        tr = pd.concat([(h - l).abs(), (h - prev_c).abs(), (l - prev_c).abs()], axis=1).max(axis=1)
        atr = tr.ewm(span=14, adjust=False).mean()
        atr_eff = atr.where(atr > 0.0, np.nan)

        roll_high = h.rolling(lookback_bars, min_periods=max(20, lookback_bars // 6)).max().shift(1)
        roll_low = l.rolling(lookback_bars, min_periods=max(20, lookback_bars // 6)).min().shift(1)
        height = (roll_high - roll_low).astype(float)
        height_eff = height.where(height > 0.0, np.nan)
        height_atr = (height_eff / (atr_eff + eps)).astype(float)
        range_ok = height_atr.notna() & (height_atr >= min_range_height_atr) & (height_atr <= max_range_height_atr)

        deep_long = (roll_high - height_eff * deep_ratio).astype(float)
        deep_short = (roll_low + height_eff * deep_ratio).astype(float)

        wick_breach_long = ((deep_long - l).clip(lower=0.0) / (atr_eff + eps)).astype(float)
        wick_breach_short = ((h - deep_short).clip(lower=0.0) / (atr_eff + eps)).astype(float)
        close_breach_long = ((deep_long - c).clip(lower=0.0) / (atr_eff + eps)).astype(float)
        close_breach_short = ((c - deep_short).clip(lower=0.0) / (atr_eff + eps)).astype(float)

        rng = (h - l).astype(float)
        rng_eff = rng.where(rng > 0.0, np.nan)
        body = (c - o).abs().astype(float)
        body_ratio = (body / (rng_eff + eps)).astype(float)
        close_pos = ((c - l) / (rng_eff + eps)).astype(float)
        upper_r = ((h - np.maximum(o, c)) / (rng_eff + eps)).astype(float)
        lower_r = ((np.minimum(o, c) - l) / (rng_eff + eps)).astype(float)

        reclaim_long = (wick_breach_long > eps) & (close_breach_long <= eps)
        reclaim_short = (wick_breach_short > eps) & (close_breach_short <= eps)
        wick_ok_long = (lower_r >= wick_ratio_min) & (close_pos >= close_pos_min)
        wick_ok_short = (upper_r >= wick_ratio_min) & (close_pos <= (1.0 - close_pos_min))
        strong_long = (c > o) & (body_ratio >= body_ratio_min) & (close_pos >= strong_close_pos_min) & wick_ok_long
        strong_short = (c < o) & (body_ratio >= body_ratio_min) & (close_pos <= (1.0 - strong_close_pos_min)) & wick_ok_short

        stage_long = pd.Series(
            np.select(
                [
                    wick_breach_long <= eps,
                    (wick_breach_long > eps) & (~reclaim_long),
                    reclaim_long & (~strong_long),
                ],
                [0, 1, 2],
                default=3,
            ),
            index=ohlc.index,
            dtype=float,
        ).where(range_ok)
        stage_short = pd.Series(
            np.select(
                [
                    wick_breach_short <= eps,
                    (wick_breach_short > eps) & (~reclaim_short),
                    reclaim_short & (~strong_short),
                ],
                [0, 1, 2],
                default=3,
            ),
            index=ohlc.index,
            dtype=float,
        ).where(range_ok)

        return pd.DataFrame(
            {
                "stage_long": stage_long,
                "stage_short": stage_short,
                "wick_breach_long": wick_breach_long.where(range_ok),
                "wick_breach_short": wick_breach_short.where(range_ok),
                "close_breach_long": close_breach_long.where(range_ok),
                "close_breach_short": close_breach_short.where(range_ok),
                "reclaim_long": reclaim_long.astype(float).where(range_ok),
                "reclaim_short": reclaim_short.astype(float).where(range_ok),
                "height_atr": height_atr.where(range_ok),
            },
            index=ohlc.index,
        )

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        stage_vals: List[float] = []
        wick_vals: List[float] = []
        close_vals: List[float] = []
        reclaim_vals: List[float] = []
        height_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                stage_vals.append(float("nan"))
                wick_vals.append(float("nan"))
                close_vals.append(float("nan"))
                reclaim_vals.append(float("nan"))
                height_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                stage_vals.append(float("nan"))
                wick_vals.append(float("nan"))
                close_vals.append(float("nan"))
                reclaim_vals.append(float("nan"))
                height_vals.append(float("nan"))
                continue

            if side_s.iloc[i] == "SHORT":
                st = float(feats["stage_short"].iloc[j])
                wb = float(feats["wick_breach_short"].iloc[j])
                cb = float(feats["close_breach_short"].iloc[j])
                rf = float(feats["reclaim_short"].iloc[j])
            else:
                st = float(feats["stage_long"].iloc[j])
                wb = float(feats["wick_breach_long"].iloc[j])
                cb = float(feats["close_breach_long"].iloc[j])
                rf = float(feats["reclaim_long"].iloc[j])
            ha = float(feats["height_atr"].iloc[j])

            if not np.isfinite(st):
                stage_vals.append(float("nan"))
                wick_vals.append(float("nan"))
                close_vals.append(float("nan"))
                reclaim_vals.append(float("nan"))
                height_vals.append(float("nan"))
                continue
            stage_vals.append(st)
            wick_vals.append(wb)
            close_vals.append(cb)
            reclaim_vals.append(rf)
            height_vals.append(ha)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["tk_tp3_ext_stage_1h"] = stage_vals
        dfm["tk_tp3_wick_breach_atr_1h"] = wick_vals
        dfm["tk_tp3_close_breach_atr_1h"] = close_vals
        dfm["tk_tp3_reclaim_flag_1h"] = reclaim_vals
        dfm["tk_tp3_range_height_atr_1h"] = height_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "tk_tp3_ext_stage_1h",
                    "tk_tp3_wick_breach_atr_1h",
                    "tk_tp3_close_breach_atr_1h",
                    "tk_tp3_reclaim_flag_1h",
                    "tk_tp3_range_height_atr_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["tk_tp3_ext_stage_1h", "tk_tp3_reclaim_flag_1h"]:
            xs = pd.to_numeric(dfm[feat], errors="coerce")
            m = xs.notna()
            if int(m.sum()) < 20:
                continue
            dfx = dfm[m].copy()
            dfx["_x"] = xs[m].astype(float).to_numpy()
            for v, g in dfx.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

        feat = "tk_tp3_wick_breach_atr_1h"
        xs = pd.to_numeric(dfm[feat], errors="coerce")
        m = xs.notna()
        if int(m.sum()) >= 50 and float(xs[m].nunique()) >= 4.0:
            dfx = dfm[m].copy()
            dfx["_x"] = xs[m].astype(float).to_numpy()
            try:
                cat = pd.qcut(dfx["_x"], q=4, duplicates="drop")
            except Exception:
                cat = None
            if cat is not None:
                q_actual = int(getattr(cat, "cat").categories.size)
                if q_actual >= 2:
                    dfx["_bucket"] = (cat.cat.codes.astype(int) + 1).map(lambda z: f"q{q_actual}_bin{int(z)}")
                    for b, g in dfx.groupby("_bucket", sort=True):
                        _add_bucket_rows(
                            bucket_rows,
                            symbol=sym_u,
                            split=str(split).strip(),
                            profile=str(profile).strip(),
                            feature=feat,
                            scheme="qtiles4",
                            bucket_id=str(b),
                            bucket_range=str(b),
                            g=g,
                        )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "tk_tp3_ext_stage_1h",
            "tk_tp3_wick_breach_atr_1h",
            "tk_tp3_close_breach_atr_1h",
            "tk_tp3_reclaim_flag_1h",
            "tk_tp3_range_height_atr_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["tk_tp3_ext_stage_1h", "tk_tp3_wick_breach_atr_1h", "tk_tp3_close_breach_atr_1h", "tk_tp3_reclaim_flag_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr", "tk_tp3_range_height_atr_1h"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty or int(sub2["_code"].nunique()) < 2:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b115_tk_r2_pullback_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    lookback_bars: int = 96,
    min_range_height_atr: float = 1.0,
    max_range_height_atr: float = 12.0,
    breakout_buffer_atr: float = 0.05,
    active_max_bars: int = 144,
    signal_zone_lo: float = 0.618,
    signal_zone_hi: float = 0.880,
    tp1_ext: float = 1.618,
    tp1_zone_hi: float = 1.880,
    tp2_ext: float = 2.618,
    tp3_ext: float = 4.236,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b115_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b115_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b115_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b115_spearman_corr_{date_tag}_v1.csv"
    out_trade = out_dir / f"b115_trade_level_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []
    trade_frames: List[pd.DataFrame] = []

    eps = 1e-12
    lookback_bars = int(lookback_bars)
    active_max_bars = int(active_max_bars)
    breakout_buffer_atr = float(breakout_buffer_atr)
    signal_zone_lo = float(signal_zone_lo)
    signal_zone_hi = float(signal_zone_hi)
    tp1_ext = float(tp1_ext)
    tp1_zone_hi = float(tp1_zone_hi)
    tp2_ext = float(tp2_ext)
    tp3_ext = float(tp3_ext)

    def _overlap(bar_lo: float, bar_hi: float, zone_a: float, zone_b: float) -> bool:
        lo = min(zone_a, zone_b)
        hi = max(zone_a, zone_b)
        return bool(np.isfinite(bar_lo) and np.isfinite(bar_hi) and (bar_hi >= lo) and (bar_lo <= hi))

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        o = pd.to_numeric(ohlc["open"], errors="coerce").astype(float)
        h = pd.to_numeric(ohlc["high"], errors="coerce").astype(float)
        l = pd.to_numeric(ohlc["low"], errors="coerce").astype(float)
        c = pd.to_numeric(ohlc["close"], errors="coerce").astype(float)

        prev_c = c.shift(1)
        tr = pd.concat([(h - l).abs(), (h - prev_c).abs(), (l - prev_c).abs()], axis=1).max(axis=1)
        atr = tr.ewm(span=14, adjust=False).mean()
        atr_eff = atr.where(atr > 0.0, np.nan)

        roll_high = h.rolling(lookback_bars, min_periods=max(20, lookback_bars // 6)).max().shift(1)
        roll_low = l.rolling(lookback_bars, min_periods=max(20, lookback_bars // 6)).min().shift(1)
        height = (roll_high - roll_low).astype(float)
        height_eff = height.where(height > 0.0, np.nan)
        height_atr = (height_eff / (atr_eff + eps)).astype(float)
        range_ok = height_atr.notna() & (height_atr >= min_range_height_atr) & (height_atr <= max_range_height_atr)

        breakout_long = (c > (roll_high + breakout_buffer_atr * atr_eff)) & range_ok
        breakout_short = (c < (roll_low - breakout_buffer_atr * atr_eff)) & range_ok

        n = int(len(ohlc))
        leg_side = np.full(n, np.nan, dtype=float)
        stage = np.full(n, np.nan, dtype=float)
        zone_type = np.full(n, np.nan, dtype=float)
        zone_hit = np.full(n, np.nan, dtype=float)
        cancel_flag = np.full(n, np.nan, dtype=float)
        retrace_depth = np.full(n, np.nan, dtype=float)

        active_side = 0
        active_start = -1
        base = np.nan
        setup = np.nan
        leg_h = np.nan
        peak = np.nan
        trough = np.nan
        ever_hit = False

        for i in range(n):
            if bool(breakout_long.iloc[i]) and not bool(breakout_short.iloc[i]):
                if active_side != 1 or active_start < 0 or (i - active_start) > active_max_bars:
                    active_side = 1
                    active_start = i
                    base = float(roll_low.iloc[i])
                    setup = float(roll_high.iloc[i])
                    leg_h = float(height_eff.iloc[i])
                    peak = max(float(h.iloc[i]), setup)
                    trough = np.nan
                    ever_hit = False
            elif bool(breakout_short.iloc[i]) and not bool(breakout_long.iloc[i]):
                if active_side != -1 or active_start < 0 or (i - active_start) > active_max_bars:
                    active_side = -1
                    active_start = i
                    base = float(roll_high.iloc[i])
                    setup = float(roll_low.iloc[i])
                    leg_h = float(height_eff.iloc[i])
                    trough = min(float(l.iloc[i]), setup)
                    peak = np.nan
                    ever_hit = False

            if active_side == 0 or active_start < 0 or not np.isfinite(leg_h) or leg_h <= 0.0:
                continue
            if (i - active_start) > active_max_bars:
                active_side = 0
                active_start = -1
                continue

            leg_side[i] = float(active_side)

            if active_side == 1:
                peak = max(float(peak), float(h.iloc[i])) if np.isfinite(peak) else float(h.iloc[i])
                tp1 = base + tp1_ext * leg_h
                tp2 = base + tp2_ext * leg_h
                tp3 = base + tp3_ext * leg_h
                signal_a = base + signal_zone_lo * leg_h
                signal_b = base + signal_zone_hi * leg_h
                trans_a = base + tp1_ext * leg_h
                trans_b = base + tp1_zone_hi * leg_h
                if peak < tp1:
                    st = 0.0
                elif peak < tp2:
                    st = 1.0
                elif peak < tp3:
                    st = 2.0
                else:
                    st = 3.0
                hit_signal_now = bool(st == 1.0 and _overlap(float(l.iloc[i]), float(h.iloc[i]), signal_a, signal_b))
                hit_trans_now = bool(st >= 2.0 and _overlap(float(l.iloc[i]), float(h.iloc[i]), trans_a, trans_b))
                denom = peak - base
                retr = (peak - float(c.iloc[i])) / denom if denom > eps else np.nan
            else:
                trough = min(float(trough), float(l.iloc[i])) if np.isfinite(trough) else float(l.iloc[i])
                tp1 = base - tp1_ext * leg_h
                tp2 = base - tp2_ext * leg_h
                tp3 = base - tp3_ext * leg_h
                signal_a = base - signal_zone_lo * leg_h
                signal_b = base - signal_zone_hi * leg_h
                trans_a = base - tp1_ext * leg_h
                trans_b = base - tp1_zone_hi * leg_h
                if trough > tp1:
                    st = 0.0
                elif trough > tp2:
                    st = 1.0
                elif trough > tp3:
                    st = 2.0
                else:
                    st = 3.0
                hit_signal_now = bool(st == 1.0 and _overlap(float(l.iloc[i]), float(h.iloc[i]), signal_a, signal_b))
                hit_trans_now = bool(st >= 2.0 and _overlap(float(l.iloc[i]), float(h.iloc[i]), trans_a, trans_b))
                denom = base - trough
                retr = (float(c.iloc[i]) - trough) / denom if denom > eps else np.nan

            if hit_signal_now or hit_trans_now:
                ever_hit = True
            stage[i] = st
            zone_type[i] = 1.0 if hit_signal_now else 2.0 if hit_trans_now else 0.0
            zone_hit[i] = 1.0 if (hit_signal_now or hit_trans_now) else 0.0
            cancel_flag[i] = 1.0 if (st >= 3.0 and not ever_hit) else 0.0
            retrace_depth[i] = float(retr) if np.isfinite(retr) else np.nan

        out = pd.DataFrame(
            {
                "leg_side": pd.Series(leg_side, index=ohlc.index),
                "stage": pd.Series(stage, index=ohlc.index),
                "zone_type": pd.Series(zone_type, index=ohlc.index),
                "zone_hit": pd.Series(zone_hit, index=ohlc.index),
                "cancel_flag": pd.Series(cancel_flag, index=ohlc.index),
                "retrace_depth": pd.Series(retrace_depth, index=ohlc.index),
                "range_height_atr": height_atr.where(range_ok),
            },
            index=ohlc.index,
        )
        return out

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")

        picked = 0
        side_vals: List[float] = []
        stage_vals: List[float] = []
        zone_type_vals: List[float] = []
        zone_hit_vals: List[float] = []
        cancel_vals: List[float] = []
        retrace_vals: List[float] = []
        height_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                side_vals.append(float("nan"))
                stage_vals.append(float("nan"))
                zone_type_vals.append(float("nan"))
                zone_hit_vals.append(float("nan"))
                cancel_vals.append(float("nan"))
                retrace_vals.append(float("nan"))
                height_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                side_vals.append(float("nan"))
                stage_vals.append(float("nan"))
                zone_type_vals.append(float("nan"))
                zone_hit_vals.append(float("nan"))
                cancel_vals.append(float("nan"))
                retrace_vals.append(float("nan"))
                height_vals.append(float("nan"))
                continue

            st = float(feats["stage"].iloc[j])
            if not np.isfinite(st):
                side_vals.append(float("nan"))
                stage_vals.append(float("nan"))
                zone_type_vals.append(float("nan"))
                zone_hit_vals.append(float("nan"))
                cancel_vals.append(float("nan"))
                retrace_vals.append(float("nan"))
                height_vals.append(float("nan"))
                continue

            side_vals.append(float(feats["leg_side"].iloc[j]))
            stage_vals.append(st)
            zone_type_vals.append(float(feats["zone_type"].iloc[j]))
            zone_hit_vals.append(float(feats["zone_hit"].iloc[j]))
            cancel_vals.append(float(feats["cancel_flag"].iloc[j]))
            retrace_vals.append(float(feats["retrace_depth"].iloc[j]))
            height_vals.append(float(feats["range_height_atr"].iloc[j]))
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["tk_r2_leg_side_1h"] = side_vals
        dfm["tk_r2_stage_1h"] = stage_vals
        dfm["tk_r2_zone_type_1h"] = zone_type_vals
        dfm["tk_r2_zone_hit_flag_1h"] = zone_hit_vals
        dfm["tk_r2_cancel_no_retrace_flag_1h"] = cancel_vals
        dfm["tk_r2_retrace_depth_1h"] = retrace_vals
        dfm["tk_r2_range_height_atr_1h"] = height_vals
        dfm["symbol"] = sym_u
        dfm["split"] = str(split).strip()
        dfm["profile"] = str(profile).strip()

        trade_cols = [
            "symbol",
            "split",
            "profile",
            "entry_time",
            "side",
            "trade_pnl",
            "win",
            "stop_loss_any",
            "tp2_any",
            "entry_score",
            "e1_break_strength_atr",
            "tk_r2_leg_side_1h",
            "tk_r2_stage_1h",
            "tk_r2_zone_type_1h",
            "tk_r2_zone_hit_flag_1h",
            "tk_r2_cancel_no_retrace_flag_1h",
            "tk_r2_retrace_depth_1h",
            "tk_r2_range_height_atr_1h",
        ]
        trade_frames.append(dfm[[c for c in trade_cols if c in dfm.columns]].copy())

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "tk_r2_stage_1h",
                    "tk_r2_zone_type_1h",
                    "tk_r2_zone_hit_flag_1h",
                    "tk_r2_cancel_no_retrace_flag_1h",
                    "tk_r2_retrace_depth_1h",
                    "tk_r2_range_height_atr_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in [
            "tk_r2_stage_1h",
            "tk_r2_zone_type_1h",
            "tk_r2_zone_hit_flag_1h",
            "tk_r2_cancel_no_retrace_flag_1h",
        ]:
            xs = pd.to_numeric(dfm[feat], errors="coerce")
            m = xs.notna()
            if int(m.sum()) < 20:
                continue
            dfx = dfm[m].copy()
            dfx["_x"] = xs[m].astype(float).to_numpy()
            for v, g in dfx.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

        feat = "tk_r2_retrace_depth_1h"
        xs = pd.to_numeric(dfm[feat], errors="coerce")
        m = xs.notna()
        if int(m.sum()) >= 50 and float(xs[m].nunique()) >= 4.0:
            dfx = dfm[m].copy()
            dfx["_x"] = xs[m].astype(float).to_numpy()
            try:
                cat = pd.qcut(dfx["_x"], q=4, duplicates="drop")
            except Exception:
                cat = None
            if cat is not None:
                q_actual = int(getattr(cat, "cat").categories.size)
                if q_actual >= 2:
                    dfx["_bucket"] = (cat.cat.codes.astype(int) + 1).map(lambda z: f"q{q_actual}_bin{int(z)}")
                    for b, g in dfx.groupby("_bucket", sort=True):
                        _add_bucket_rows(
                            bucket_rows,
                            symbol=sym_u,
                            split=str(split).strip(),
                            profile=str(profile).strip(),
                            feature=feat,
                            scheme="qtiles4",
                            bucket_id=str(b),
                            bucket_range=str(b),
                            g=g,
                        )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "tk_r2_stage_1h",
            "tk_r2_zone_type_1h",
            "tk_r2_zone_hit_flag_1h",
            "tk_r2_cancel_no_retrace_flag_1h",
            "tk_r2_retrace_depth_1h",
            "tk_r2_range_height_atr_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in [
            "tk_r2_stage_1h",
            "tk_r2_zone_type_1h",
            "tk_r2_zone_hit_flag_1h",
            "tk_r2_cancel_no_retrace_flag_1h",
            "tk_r2_retrace_depth_1h",
        ]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr", "tk_r2_range_height_atr_1h"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty or int(sub2["_code"].nunique()) < 2:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    trade_df = pd.concat(trade_frames, ignore_index=True) if trade_frames else pd.DataFrame()
    trade_df.to_csv(out_trade, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr, "TRADE_LEVEL": out_trade}


def run_b57_kd_saturation_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    overbought: float = 80.0,
    oversold: float = 20.0,
    extreme_overbought: float = 95.0,
    extreme_oversold: float = 5.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b57_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b57_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b57_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b57_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    base_p = Params()
    overbought = float(overbought)
    oversold = float(oversold)
    extreme_overbought = float(extreme_overbought)
    extreme_oversold = float(extreme_oversold)

    def _consec_count(flag: np.ndarray) -> np.ndarray:
        out = np.zeros(int(len(flag)), dtype=int)
        run = 0
        for i in range(int(len(flag))):
            if bool(flag[i]):
                run += 1
            else:
                run = 0
            out[i] = run
        return out

    def _run_bucket(run: np.ndarray) -> np.ndarray:
        r = run.astype(float)
        return np.select([r <= 0.0, r <= 2.0, r <= 5.0], [0, 1, 2], default=3).astype(int)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        kd1d = kdj(d1[["high", "low", "close"]], int(base_p.kdj_n), int(base_p.kdj_m1), int(base_p.kdj_m2))
        d1 = d1.copy()
        d1["kd_k"] = kd1d["k"]

        k = pd.to_numeric(d1["kd_k"], errors="coerce").astype(float)
        valid = k.notna()
        ob = (k >= overbought).fillna(False)
        os = (k <= oversold).fillna(False)

        run_ob = pd.Series(_consec_count(ob.to_numpy(dtype=bool)), index=d1.index).astype(float).where(valid)
        run_os = pd.Series(_consec_count(os.to_numpy(dtype=bool)), index=d1.index).astype(float).where(valid)
        buck_ob = pd.Series(_run_bucket(run_ob.fillna(0.0).to_numpy(dtype=int)), index=d1.index).astype(float).where(valid)
        buck_os = pd.Series(_run_bucket(run_os.fillna(0.0).to_numpy(dtype=int)), index=d1.index).astype(float).where(valid)

        state = np.select([ob.to_numpy(dtype=bool), os.to_numpy(dtype=bool)], [1, 2], default=0).astype(int)
        prev_state = np.roll(state, 1)
        prev_state[0] = 0
        exit_code = np.select([(state == 0) & (prev_state == 1), (state == 0) & (prev_state == 2)], [1, 2], default=0).astype(float)
        exit_code_s = pd.Series(exit_code, index=d1.index).where(valid)

        ext_ob = ((k >= extreme_overbought).astype(float)).where(valid)
        ext_os = ((k <= extreme_oversold).astype(float)).where(valid)
        ob_flag = (ob.astype(float)).where(valid)
        os_flag = (os.astype(float)).where(valid)

        d1_fields = pd.DataFrame(
            {
                "ob_flag": ob_flag,
                "os_flag": os_flag,
                "ob_bucket": buck_ob,
                "os_bucket": buck_os,
                "exit_code": exit_code_s,
                "ext_ob": ext_ob,
                "ext_os": ext_os,
            },
            index=d1.index,
        )

        a1d = align_last_closed(d1_fields, ohlc.index)
        for c in a1d.columns:
            a1d[c] = pd.to_numeric(a1d[c], errors="coerce")
        return a1d

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        favor_bucket_vals: List[float] = []
        unfavor_bucket_vals: List[float] = []
        favor_exit_vals: List[float] = []
        unfavor_exit_vals: List[float] = []
        favor_extreme_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                favor_bucket_vals.append(float("nan"))
                unfavor_bucket_vals.append(float("nan"))
                favor_exit_vals.append(float("nan"))
                unfavor_exit_vals.append(float("nan"))
                favor_extreme_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                favor_bucket_vals.append(float("nan"))
                unfavor_bucket_vals.append(float("nan"))
                favor_exit_vals.append(float("nan"))
                unfavor_exit_vals.append(float("nan"))
                favor_extreme_vals.append(float("nan"))
                continue

            exit_code = float(feats["exit_code"].iloc[j]) if "exit_code" in feats.columns else float("nan")
            if side_s.iloc[i] == "SHORT":
                fb = float(feats["ob_bucket"].iloc[j])
                ub = float(feats["os_bucket"].iloc[j])
                fe = float((exit_code == 1.0)) if np.isfinite(exit_code) else float("nan")
                ue = float((exit_code == 2.0)) if np.isfinite(exit_code) else float("nan")
                fx = float(feats["ext_ob"].iloc[j])
            else:
                fb = float(feats["os_bucket"].iloc[j])
                ub = float(feats["ob_bucket"].iloc[j])
                fe = float((exit_code == 2.0)) if np.isfinite(exit_code) else float("nan")
                ue = float((exit_code == 1.0)) if np.isfinite(exit_code) else float("nan")
                fx = float(feats["ext_os"].iloc[j])

            if not (np.isfinite(fb) and np.isfinite(ub)):
                favor_bucket_vals.append(float("nan"))
                unfavor_bucket_vals.append(float("nan"))
                favor_exit_vals.append(float("nan"))
                unfavor_exit_vals.append(float("nan"))
                favor_extreme_vals.append(float("nan"))
                continue
            favor_bucket_vals.append(fb)
            unfavor_bucket_vals.append(ub)
            favor_exit_vals.append(fe)
            unfavor_exit_vals.append(ue)
            favor_extreme_vals.append(fx)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["kd_sat_favor_bucket_1h"] = favor_bucket_vals
        dfm["kd_sat_unfavor_bucket_1h"] = unfavor_bucket_vals
        dfm["kd_sat_favor_exit_1h"] = favor_exit_vals
        dfm["kd_sat_unfavor_exit_1h"] = unfavor_exit_vals
        dfm["kd_sat_favor_extreme_1h"] = favor_extreme_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "kd_sat_favor_bucket_1h",
                    "kd_sat_unfavor_bucket_1h",
                    "kd_sat_favor_exit_1h",
                    "kd_sat_unfavor_exit_1h",
                    "kd_sat_favor_extreme_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in [
            "kd_sat_favor_bucket_1h",
            "kd_sat_unfavor_bucket_1h",
            "kd_sat_favor_exit_1h",
            "kd_sat_unfavor_exit_1h",
            "kd_sat_favor_extreme_1h",
        ]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "kd_sat_favor_bucket_1h",
            "kd_sat_unfavor_bucket_1h",
            "kd_sat_favor_exit_1h",
            "kd_sat_unfavor_exit_1h",
            "kd_sat_favor_extreme_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in [
            "kd_sat_favor_bucket_1h",
            "kd_sat_unfavor_bucket_1h",
            "kd_sat_favor_exit_1h",
            "kd_sat_unfavor_exit_1h",
            "kd_sat_favor_extreme_1h",
        ]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b57_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b57_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b57_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue

        max_code = int(sub2["_code"].max())
        if str(feat).endswith("_bucket_1h") and max_code >= 1:
            a = sub2[sub2["_code"] <= 0].copy()
            b = sub2[sub2["_code"] >= 1].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4=0",
                    "group_b": "code4>=1",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_0_vs_ge1",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b58_ema_reclaim_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    ema_span: int = 21,
    min_body_atr: float = 0.50,
    min_reclaim_dist_atr: float = 0.10,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b58_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b58_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b58_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b58_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    base_p = Params()
    ema_span = int(ema_span)
    min_body_atr = float(min_body_atr)
    min_reclaim_dist_atr = float(min_reclaim_dist_atr)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        o = pd.to_numeric(ohlc["open"], errors="coerce").astype(float)
        h = pd.to_numeric(ohlc["high"], errors="coerce").astype(float)
        l = pd.to_numeric(ohlc["low"], errors="coerce").astype(float)
        c = pd.to_numeric(ohlc["close"], errors="coerce").astype(float)

        prev_c = c.shift(1)
        tr = pd.concat([(h - l).abs(), (h - prev_c).abs(), (l - prev_c).abs()], axis=1).max(axis=1)
        atr_v = tr.ewm(span=14, adjust=False).mean()
        atr_eff = atr_v.where(atr_v > 0.0, np.nan)

        ema_v = c.ewm(span=ema_span, adjust=False).mean()

        body = (c - o).abs().astype(float)
        body_ok = (body >= (min_body_atr * (atr_eff + eps))).astype(int)

        touch_long = (l <= (ema_v - base_p.touch_k * (atr_eff + eps))).astype(int)
        touch_short = (h >= (ema_v + base_p.touch_k * (atr_eff + eps))).astype(int)

        fake_long = ((touch_long == 1) & (c > ema_v)).astype(int)
        fake_short = ((touch_short == 1) & (c < ema_v)).astype(int)

        wick_ok_long = (l >= (ema_v - base_p.shadow_k * (atr_eff + eps))).astype(int)
        wick_ok_short = (h <= (ema_v + base_p.shadow_k * (atr_eff + eps))).astype(int)

        reclaim_dist_long = ((c - ema_v) / (atr_eff + eps)).astype(float)
        reclaim_dist_short = ((ema_v - c) / (atr_eff + eps)).astype(float)
        dist_ok_long = (reclaim_dist_long >= min_reclaim_dist_atr).astype(int)
        dist_ok_short = (reclaim_dist_short >= min_reclaim_dist_atr).astype(int)

        reclaim_long = ((c > ema_v) & (c > o) & (wick_ok_long == 1) & (body_ok == 1)).astype(int)
        reclaim_short = ((c < ema_v) & (c < o) & (wick_ok_short == 1) & (body_ok == 1)).astype(int)

        score_long = (fake_long + reclaim_long + (reclaim_long & (dist_ok_long == 1)).astype(int)).astype(int).clip(0, 3)
        score_short = (fake_short + reclaim_short + (reclaim_short & (dist_ok_short == 1)).astype(int)).astype(int).clip(0, 3)

        return pd.DataFrame(
            {
                "touch_long": touch_long.astype(int),
                "touch_short": touch_short.astype(int),
                "fake_long": fake_long.astype(int),
                "fake_short": fake_short.astype(int),
                "reclaim_long": reclaim_long.astype(int),
                "reclaim_short": reclaim_short.astype(int),
                "score_long": score_long.astype(int),
                "score_short": score_short.astype(int),
            },
            index=ohlc.index,
        )

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        touch_vals: List[float] = []
        fake_vals: List[float] = []
        reclaim_vals: List[float] = []
        score_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                touch_vals.append(float("nan"))
                fake_vals.append(float("nan"))
                reclaim_vals.append(float("nan"))
                score_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                touch_vals.append(float("nan"))
                fake_vals.append(float("nan"))
                reclaim_vals.append(float("nan"))
                score_vals.append(float("nan"))
                continue
            if side_s.iloc[i] == "SHORT":
                t0 = float(feats["touch_short"].iloc[j])
                f0 = float(feats["fake_short"].iloc[j])
                r0 = float(feats["reclaim_short"].iloc[j])
                s0 = float(feats["score_short"].iloc[j])
            else:
                t0 = float(feats["touch_long"].iloc[j])
                f0 = float(feats["fake_long"].iloc[j])
                r0 = float(feats["reclaim_long"].iloc[j])
                s0 = float(feats["score_long"].iloc[j])

            if not (np.isfinite(t0) and np.isfinite(f0) and np.isfinite(r0) and np.isfinite(s0)):
                touch_vals.append(float("nan"))
                fake_vals.append(float("nan"))
                reclaim_vals.append(float("nan"))
                score_vals.append(float("nan"))
                continue

            touch_vals.append(t0)
            fake_vals.append(f0)
            reclaim_vals.append(r0)
            score_vals.append(s0)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["ab_ema_touch_1h"] = touch_vals
        dfm["ab_ema_fake_break_1h"] = fake_vals
        dfm["ab_ema_reclaim_1h"] = reclaim_vals
        dfm["ab_ema_reclaim_score_1h"] = score_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "ab_ema_touch_1h",
                    "ab_ema_fake_break_1h",
                    "ab_ema_reclaim_1h",
                    "ab_ema_reclaim_score_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["ab_ema_touch_1h", "ab_ema_fake_break_1h", "ab_ema_reclaim_1h", "ab_ema_reclaim_score_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "ab_ema_touch_1h",
            "ab_ema_fake_break_1h",
            "ab_ema_reclaim_1h",
            "ab_ema_reclaim_score_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["ab_ema_touch_1h", "ab_ema_fake_break_1h", "ab_ema_reclaim_1h", "ab_ema_reclaim_score_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b58_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b58_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b58_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue
        max_code = int(sub2["_code"].max())

        if max_code >= 2 and str(feat).endswith("_score_1h"):
            a = sub2[sub2["_code"] <= 0].copy()
            b = sub2[sub2["_code"] >= 1].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4=0",
                    "group_b": "code4>=1",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_0_vs_ge1",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b59_ema_regime_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    ema_fast_span: int = 20,
    ema200_daily_span: int = 200,
    slope_lookback_bars: int = 12,
    slope_flat_abs: float = 0.02,
    slope_strong_abs: float = 0.08,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b59_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b59_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b59_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b59_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    ema_fast_span = int(ema_fast_span)
    ema200_daily_span = int(ema200_daily_span)
    slope_lookback_bars = int(slope_lookback_bars)
    slope_flat_abs = float(slope_flat_abs)
    slope_strong_abs = float(slope_strong_abs)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        o = pd.to_numeric(ohlc["open"], errors="coerce").astype(float)
        h = pd.to_numeric(ohlc["high"], errors="coerce").astype(float)
        l = pd.to_numeric(ohlc["low"], errors="coerce").astype(float)
        c = pd.to_numeric(ohlc["close"], errors="coerce").astype(float)

        prev_c = c.shift(1)
        tr = pd.concat([(h - l).abs(), (h - prev_c).abs(), (l - prev_c).abs()], axis=1).max(axis=1)
        atr_v = tr.ewm(span=14, adjust=False).mean()
        atr_eff = atr_v.where(atr_v > 0.0, np.nan)

        ema20 = c.ewm(span=ema_fast_span, adjust=False).mean()
        slope = (ema20 - ema20.shift(slope_lookback_bars)) / (atr_eff * float(slope_lookback_bars) + eps)

        slope_bucket = np.select(
            [
                slope <= -slope_strong_abs,
                slope <= -slope_flat_abs,
                slope < slope_flat_abs,
            ],
            [0, 1, 2],
            default=3,
        ).astype(int)

        side_ema20 = (c >= ema20).astype(int)

        d1 = resample_ohlcv(ohlc, "1D")
        d1c = pd.to_numeric(d1["close"], errors="coerce").astype(float)
        d1_ema200 = d1c.ewm(span=ema200_daily_span, adjust=False).mean()
        d1_fields = pd.DataFrame({"ema200": d1_ema200.astype(float)}, index=d1.index)
        ema200_1h = align_last_closed(d1_fields, ohlc.index)["ema200"]
        side_ema200 = (c >= ema200_1h).astype(int)

        stack = (ema20 >= ema200_1h).astype(int)

        return pd.DataFrame(
            {
                "ab_ema20_slope_bucket_1h": pd.Series(slope_bucket, index=ohlc.index).astype(int),
                "ab_ema20_side_1h": side_ema20.astype(int),
                "ab_ema200_side_1h": side_ema200.astype(int),
                "ab_ema20_gt_ema200_1h": stack.astype(int),
            },
            index=ohlc.index,
        )

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        slope_vals: List[float] = []
        side20_vals: List[float] = []
        side200_vals: List[float] = []
        stack_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                slope_vals.append(float("nan"))
                side20_vals.append(float("nan"))
                side200_vals.append(float("nan"))
                stack_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                slope_vals.append(float("nan"))
                side20_vals.append(float("nan"))
                side200_vals.append(float("nan"))
                stack_vals.append(float("nan"))
                continue

            sl0 = float(feats["ab_ema20_slope_bucket_1h"].iloc[j])
            s20 = float(feats["ab_ema20_side_1h"].iloc[j])
            s200 = float(feats["ab_ema200_side_1h"].iloc[j])
            st = float(feats["ab_ema20_gt_ema200_1h"].iloc[j])

            if not (np.isfinite(sl0) and np.isfinite(s20) and np.isfinite(s200) and np.isfinite(st)):
                slope_vals.append(float("nan"))
                side20_vals.append(float("nan"))
                side200_vals.append(float("nan"))
                stack_vals.append(float("nan"))
                continue

            slope_vals.append(sl0)
            side20_vals.append(s20)
            side200_vals.append(s200)
            stack_vals.append(st)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["ab_ema20_slope_bucket_1h"] = slope_vals
        dfm["ab_ema20_side_1h"] = side20_vals
        dfm["ab_ema200_side_1h"] = side200_vals
        dfm["ab_ema20_gt_ema200_1h"] = stack_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "ab_ema20_slope_bucket_1h",
                    "ab_ema20_side_1h",
                    "ab_ema200_side_1h",
                    "ab_ema20_gt_ema200_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["ab_ema20_slope_bucket_1h", "ab_ema20_side_1h", "ab_ema200_side_1h", "ab_ema20_gt_ema200_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "ab_ema20_slope_bucket_1h",
            "ab_ema20_side_1h",
            "ab_ema200_side_1h",
            "ab_ema20_gt_ema200_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["ab_ema20_slope_bucket_1h", "ab_ema20_side_1h", "ab_ema200_side_1h", "ab_ema20_gt_ema200_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b59_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b59_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b59_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue

        max_code = int(sub2["_code"].max())
        if str(feat).endswith("_slope_bucket_1h") and max_code >= 3:
            a = sub2[sub2["_code"] <= 1].copy()
            b = sub2[sub2["_code"] >= 2].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4<=1",
                    "group_b": "code4>=2",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_le1_vs_ge2",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b61_kd_divergence_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    left_bars: int = 3,
    right_bars: int = 3,
    min_price_move_atr: float = 0.50,
    min_k_diff: float = 5.0,
    overbought: float = 70.0,
    oversold: float = 30.0,
    min_body_atr: float = 0.50,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b61_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b61_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b61_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b61_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    base_p = Params()
    left_bars = int(left_bars)
    right_bars = int(right_bars)
    min_price_move_atr = float(min_price_move_atr)
    min_k_diff = float(min_k_diff)
    overbought = float(overbought)
    oversold = float(oversold)
    min_body_atr = float(min_body_atr)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        for c in ["open", "high", "low", "close"]:
            d1[c] = pd.to_numeric(d1[c], errors="coerce")

        kd1d = kdj(d1[["high", "low", "close"]], int(base_p.kdj_n), int(base_p.kdj_m1), int(base_p.kdj_m2))
        k = pd.to_numeric(kd1d["k"], errors="coerce").astype(float)

        prev_c = d1["close"].shift(1)
        tr = pd.concat([(d1["high"] - d1["low"]).abs(), (d1["high"] - prev_c).abs(), (d1["low"] - prev_c).abs()], axis=1).max(axis=1)
        atr_d = tr.ewm(span=14, adjust=False).mean()
        atr_eff = atr_d.where(atr_d > 0.0, np.nan)

        win = int(left_bars + right_bars + 1)
        low = d1["low"].astype(float)
        high = d1["high"].astype(float)
        roll_min = low.rolling(win, center=True, min_periods=win).min()
        roll_max = high.rolling(win, center=True, min_periods=win).max()
        pivot_low_raw = (low.notna() & (low == roll_min)).fillna(False)
        pivot_high_raw = (high.notna() & (high == roll_max)).fillna(False)

        pivot_low_conf = pivot_low_raw.shift(right_bars).fillna(False)
        pivot_high_conf = pivot_high_raw.shift(right_bars).fillna(False)

        bull_raw = np.zeros(int(len(d1)), dtype=int)
        bear_raw = np.zeros(int(len(d1)), dtype=int)
        bull_score = np.zeros(int(len(d1)), dtype=int)
        bear_score = np.zeros(int(len(d1)), dtype=int)

        prev_low_p: Optional[float] = None
        prev_low_k: Optional[float] = None
        prev_high_p: Optional[float] = None
        prev_high_k: Optional[float] = None
        prev_bull_div = False
        prev_bear_div = False

        o_d = pd.to_numeric(d1["open"], errors="coerce").astype(float).to_numpy()
        c_d = pd.to_numeric(d1["close"], errors="coerce").astype(float).to_numpy()
        h_d = pd.to_numeric(d1["high"], errors="coerce").astype(float).to_numpy()
        l_d = pd.to_numeric(d1["low"], errors="coerce").astype(float).to_numpy()
        k_d = k.to_numpy(dtype=float)
        atr_arr = atr_eff.to_numpy(dtype=float)
        pl_conf = pivot_low_conf.to_numpy(dtype=bool)
        ph_conf = pivot_high_conf.to_numpy(dtype=bool)

        for j in range(int(len(d1))):
            if pl_conf[j]:
                i = int(j - right_bars)
                if 0 <= i < int(len(d1)) and np.isfinite(l_d[i]) and np.isfinite(k_d[i]) and np.isfinite(atr_arr[i]):
                    if prev_low_p is not None and prev_low_k is not None:
                        price_ok = (prev_low_p - float(l_d[i])) >= (min_price_move_atr * float(atr_arr[i]))
                        k_ok = (float(k_d[i]) - float(prev_low_k)) >= min_k_diff
                        if price_ok and k_ok:
                            bull_raw[j] = 1
                            s = 1
                            if float(k_d[i]) <= oversold:
                                s += 1
                            if prev_bull_div:
                                s += 1
                            bull_score[j] = int(min(3, s))
                            prev_bull_div = True
                        else:
                            prev_bull_div = False
                    prev_low_p = float(l_d[i])
                    prev_low_k = float(k_d[i])

            if ph_conf[j]:
                i = int(j - right_bars)
                if 0 <= i < int(len(d1)) and np.isfinite(h_d[i]) and np.isfinite(k_d[i]) and np.isfinite(atr_arr[i]):
                    if prev_high_p is not None and prev_high_k is not None:
                        price_ok = (float(h_d[i]) - prev_high_p) >= (min_price_move_atr * float(atr_arr[i]))
                        k_ok = (float(prev_high_k) - float(k_d[i])) >= min_k_diff
                        if price_ok and k_ok:
                            bear_raw[j] = 1
                            s = 1
                            if float(k_d[i]) >= overbought:
                                s += 1
                            if prev_bear_div:
                                s += 1
                            bear_score[j] = int(min(3, s))
                            prev_bear_div = True
                        else:
                            prev_bear_div = False
                    prev_high_p = float(h_d[i])
                    prev_high_k = float(k_d[i])

        body = np.abs(c_d - o_d)
        bull_reversal = (c_d > o_d) & (body >= (min_body_atr * (atr_arr + eps))) & (c_d >= (l_d + 0.70 * (h_d - l_d + eps)))
        bear_reversal = (c_d < o_d) & (body >= (min_body_atr * (atr_arr + eps))) & (c_d <= (l_d + 0.30 * (h_d - l_d + eps)))

        bull_conf_score = np.roll(bull_score, 1)
        bear_conf_score = np.roll(bear_score, 1)
        bull_conf_score[0] = 0
        bear_conf_score[0] = 0
        bull_conf_score = (bull_reversal.astype(int) * bull_conf_score).astype(int)
        bear_conf_score = (bear_reversal.astype(int) * bear_conf_score).astype(int)

        d1_fields = pd.DataFrame(
            {
                "bull_score": pd.Series(bull_conf_score, index=d1.index).astype(int),
                "bear_score": pd.Series(bear_conf_score, index=d1.index).astype(int),
                "bull_flag": (pd.Series(bull_conf_score, index=d1.index).astype(int) >= 2).astype(int),
                "bear_flag": (pd.Series(bear_conf_score, index=d1.index).astype(int) >= 2).astype(int),
            },
            index=d1.index,
        )

        a1d = align_last_closed(d1_fields, ohlc.index)
        for c in a1d.columns:
            a1d[c] = pd.to_numeric(a1d[c], errors="coerce")
        return a1d

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        score_vals: List[float] = []
        flag_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                score_vals.append(float("nan"))
                flag_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                score_vals.append(float("nan"))
                flag_vals.append(float("nan"))
                continue
            if side_s.iloc[i] == "SHORT":
                s0 = float(feats["bear_score"].iloc[j])
                f0 = float(feats["bear_flag"].iloc[j])
            else:
                s0 = float(feats["bull_score"].iloc[j])
                f0 = float(feats["bull_flag"].iloc[j])

            if not (np.isfinite(s0) and np.isfinite(f0)):
                score_vals.append(float("nan"))
                flag_vals.append(float("nan"))
                continue
            score_vals.append(s0)
            flag_vals.append(f0)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["kd_div_score_1h"] = score_vals
        dfm["kd_div_flag_1h"] = flag_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "kd_div_score_1h",
                    "kd_div_flag_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["kd_div_score_1h", "kd_div_flag_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in ["trade_pnl", "kd_div_score_1h", "kd_div_flag_1h", "entry_score", "e1_break_strength_atr"]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["kd_div_score_1h", "kd_div_flag_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b61_followups(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"b61_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b61_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue

        max_code = int(sub2["_code"].max())
        if str(feat).endswith("_score_1h") and max_code >= 2:
            a = sub2[sub2["_code"] <= 0].copy()
            b = sub2[sub2["_code"] >= 1].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4=0",
                    "group_b": "code4>=1",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_0_vs_ge1",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


def run_b62_kd_basic_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    oversold: float = 20.0,
    overbought: float = 80.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b62_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b62_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b62_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b62_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    base_p = Params()
    oversold = float(oversold)
    overbought = float(overbought)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        kd1d = kdj(d1[["high", "low", "close"]], int(base_p.kdj_n), int(base_p.kdj_m1), int(base_p.kdj_m2))
        k = pd.to_numeric(kd1d["k"], errors="coerce").astype(float)
        d1_fields = pd.DataFrame({"k": k}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        a1d["k"] = pd.to_numeric(a1d["k"], errors="coerce")
        return a1d

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        bucket_vals: List[float] = []
        extreme_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue
            k0 = float(feats["k"].iloc[j]) if "k" in feats.columns else float("nan")
            if not np.isfinite(k0):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue

            favor_k = float(k0) if side_s.iloc[i] == "SHORT" else float(100.0 - k0)
            b0 = int(
                np.select(
                    [favor_k <= oversold, favor_k <= 50.0, favor_k < overbought],
                    [0, 1, 2],
                    default=3,
                )
            )
            e0 = int(favor_k >= overbought)

            bucket_vals.append(float(b0))
            extreme_vals.append(float(e0))
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["kd_basic_favor_bucket_1h"] = bucket_vals
        dfm["kd_basic_favor_extreme_1h"] = extreme_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "kd_basic_favor_bucket_1h",
                    "kd_basic_favor_extreme_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["kd_basic_favor_bucket_1h", "kd_basic_favor_extreme_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in ["trade_pnl", "kd_basic_favor_bucket_1h", "kd_basic_favor_extreme_1h", "entry_score", "e1_break_strength_atr"]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["kd_basic_favor_bucket_1h", "kd_basic_favor_extreme_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b63_kd_multitf_align_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    overbought: float = 70.0,
    oversold: float = 30.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b63_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b63_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b63_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b63_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    base_p = Params()
    overbought = float(overbought)
    oversold = float(oversold)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        h4 = resample_ohlcv(ohlc, "4H")
        if d1.empty or h4.empty:
            return pd.DataFrame(index=ohlc.index)
        kd1d = kdj(d1[["high", "low", "close"]], int(base_p.kdj_n), int(base_p.kdj_m1), int(base_p.kdj_m2))
        kd4h = kdj(h4[["high", "low", "close"]], int(base_p.kdj_n), int(base_p.kdj_m1), int(base_p.kdj_m2))
        k1 = pd.to_numeric(kd1d["k"], errors="coerce").astype(float)
        k4 = pd.to_numeric(kd4h["k"], errors="coerce").astype(float)
        d1_fields = pd.DataFrame({"k1d": k1}, index=d1.index)
        h4_fields = pd.DataFrame({"k4h": k4}, index=h4.index)
        a1 = align_last_closed(d1_fields, ohlc.index)
        a4 = align_last_closed(h4_fields, ohlc.index)
        out = pd.DataFrame(index=ohlc.index)
        out["k1d"] = pd.to_numeric(a1["k1d"], errors="coerce")
        out["k4h"] = pd.to_numeric(a4["k4h"], errors="coerce")
        return out

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        favor_vals: List[float] = []
        unfavor_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                favor_vals.append(float("nan"))
                unfavor_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                favor_vals.append(float("nan"))
                unfavor_vals.append(float("nan"))
                continue
            k1 = float(feats["k1d"].iloc[j]) if "k1d" in feats.columns else float("nan")
            k4 = float(feats["k4h"].iloc[j]) if "k4h" in feats.columns else float("nan")
            if not (np.isfinite(k1) and np.isfinite(k4)):
                favor_vals.append(float("nan"))
                unfavor_vals.append(float("nan"))
                continue

            if side_s.iloc[i] == "SHORT":
                favor = int((k1 >= overbought)) + int((k4 >= overbought))
                unfavor = int((k1 <= oversold)) + int((k4 <= oversold))
            else:
                favor = int((k1 <= oversold)) + int((k4 <= oversold))
                unfavor = int((k1 >= overbought)) + int((k4 >= overbought))

            favor_vals.append(float(favor))
            unfavor_vals.append(float(unfavor))
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["kd_align_favor_count_1h"] = favor_vals
        dfm["kd_align_unfavor_count_1h"] = unfavor_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "kd_align_favor_count_1h",
                    "kd_align_unfavor_count_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["kd_align_favor_count_1h", "kd_align_unfavor_count_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in ["trade_pnl", "kd_align_favor_count_1h", "kd_align_unfavor_count_1h", "entry_score", "e1_break_strength_atr"]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["kd_align_favor_count_1h", "kd_align_unfavor_count_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b64_kd_macd_resonance_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    fast: int = 12,
    slow: int = 26,
    signal: int = 9,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b64_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b64_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b64_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b64_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    base_p = Params()
    fast = int(fast)
    slow = int(slow)
    signal = int(signal)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        c1 = pd.to_numeric(d1["close"], errors="coerce").astype(float)
        kd1d = kdj(d1[["high", "low", "close"]], int(base_p.kdj_n), int(base_p.kdj_m1), int(base_p.kdj_m2))
        k = pd.to_numeric(kd1d["k"], errors="coerce").astype(float)

        ema_fast = c1.ewm(span=fast, adjust=False).mean()
        ema_slow = c1.ewm(span=slow, adjust=False).mean()
        macd = ema_fast - ema_slow
        macd_sig = macd.ewm(span=signal, adjust=False).mean()
        hist = macd - macd_sig
        hist_slope = hist - hist.shift(1)

        bull_score = (
            (k > 50.0).astype(int)
            + (k > k.shift(1)).astype(int)
            + (hist > 0.0).astype(int)
            + (hist_slope > 0.0).astype(int)
        ).clip(0, 4)
        bear_score = (
            (k < 50.0).astype(int)
            + (k < k.shift(1)).astype(int)
            + (hist < 0.0).astype(int)
            + (hist_slope < 0.0).astype(int)
        ).clip(0, 4)

        d1_fields = pd.DataFrame({"bull": bull_score.astype(int), "bear": bear_score.astype(int)}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        for c in a1d.columns:
            a1d[c] = pd.to_numeric(a1d[c], errors="coerce")
        return a1d

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        score_vals: List[float] = []
        flag_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                score_vals.append(float("nan"))
                flag_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                score_vals.append(float("nan"))
                flag_vals.append(float("nan"))
                continue
            if side_s.iloc[i] == "SHORT":
                s0 = float(feats["bear"].iloc[j])
            else:
                s0 = float(feats["bull"].iloc[j])
            if not np.isfinite(s0):
                score_vals.append(float("nan"))
                flag_vals.append(float("nan"))
                continue
            score_vals.append(s0)
            flag_vals.append(float(s0 >= 3.0))
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["kd_macd_res_score_1h"] = score_vals
        dfm["kd_macd_res_flag_1h"] = flag_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "kd_macd_res_score_1h",
                    "kd_macd_res_flag_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["kd_macd_res_score_1h", "kd_macd_res_flag_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in ["trade_pnl", "kd_macd_res_score_1h", "kd_macd_res_flag_1h", "entry_score", "e1_break_strength_atr"]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["kd_macd_res_score_1h", "kd_macd_res_flag_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b65_volume_patterns_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    spike_mult: float = 2.0,
    dryup_mult: float = 0.5,
    ma_window: int = 20,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b65_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b65_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b65_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b65_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    spike_mult = float(spike_mult)
    dryup_mult = float(dryup_mult)
    ma_window = int(ma_window)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        v = pd.to_numeric(ohlc.get("volume"), errors="coerce").astype(float)
        ma = v.rolling(ma_window, min_periods=max(5, ma_window // 2)).mean()
        ma_eff = ma.where(ma > 0.0, np.nan)
        ratio = (v / (ma_eff + eps)).astype(float)

        bucket = np.select(
            [ratio <= dryup_mult, ratio <= 1.0, ratio < spike_mult],
            [0, 1, 2],
            default=3,
        ).astype(int)
        dry = (ratio <= dryup_mult).astype(int)
        spike = (ratio >= spike_mult).astype(int)

        out = pd.DataFrame(
            {
                "vol_ratio_bucket_1h": pd.Series(bucket, index=ohlc.index).astype(int),
                "vol_dryup_flag_1h": pd.Series(dry, index=ohlc.index).astype(int),
                "vol_spike_flag_1h": pd.Series(spike, index=ohlc.index).astype(int),
            },
            index=ohlc.index,
        )
        out = out.where(ratio.notna())
        return out

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")

        picked = 0
        bucket_vals: List[float] = []
        dry_vals: List[float] = []
        spike_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                bucket_vals.append(float("nan"))
                dry_vals.append(float("nan"))
                spike_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                bucket_vals.append(float("nan"))
                dry_vals.append(float("nan"))
                spike_vals.append(float("nan"))
                continue
            b0 = float(feats["vol_ratio_bucket_1h"].iloc[j])
            d0 = float(feats["vol_dryup_flag_1h"].iloc[j])
            s0 = float(feats["vol_spike_flag_1h"].iloc[j])
            if not (np.isfinite(b0) and np.isfinite(d0) and np.isfinite(s0)):
                bucket_vals.append(float("nan"))
                dry_vals.append(float("nan"))
                spike_vals.append(float("nan"))
                continue
            bucket_vals.append(b0)
            dry_vals.append(d0)
            spike_vals.append(s0)
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["vol_ratio_bucket_1h"] = bucket_vals
        dfm["vol_dryup_flag_1h"] = dry_vals
        dfm["vol_spike_flag_1h"] = spike_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "vol_ratio_bucket_1h",
                    "vol_dryup_flag_1h",
                    "vol_spike_flag_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["vol_ratio_bucket_1h", "vol_dryup_flag_1h", "vol_spike_flag_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in ["trade_pnl", "vol_ratio_bucket_1h", "vol_dryup_flag_1h", "vol_spike_flag_1h", "entry_score", "e1_break_strength_atr"]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["vol_ratio_bucket_1h", "vol_dryup_flag_1h", "vol_spike_flag_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b66_rsi_basic_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    rsi_n: int = 14,
    oversold: float = 30.0,
    overbought: float = 70.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b66_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b66_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b66_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b66_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    rsi_n = int(rsi_n)
    oversold = float(oversold)
    overbought = float(overbought)

    def _rsi(close: pd.Series, n: int) -> pd.Series:
        c = pd.to_numeric(close, errors="coerce").astype(float)
        d = c.diff()
        gain = d.clip(lower=0.0)
        loss = (-d).clip(lower=0.0)
        alpha = 1.0 / float(max(1, int(n)))
        avg_gain = gain.ewm(alpha=alpha, adjust=False, min_periods=max(2, int(n))).mean()
        avg_loss = loss.ewm(alpha=alpha, adjust=False, min_periods=max(2, int(n))).mean()
        rs = avg_gain / (avg_loss + eps)
        rsi = 100.0 - (100.0 / (1.0 + rs))
        rsi = rsi.where((avg_gain + avg_loss) > 0.0)
        return rsi

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        rsi1d = _rsi(d1["close"], rsi_n)
        d1_fields = pd.DataFrame({"rsi": rsi1d}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        a1d["rsi"] = pd.to_numeric(a1d["rsi"], errors="coerce")
        return a1d

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        bucket_vals: List[float] = []
        extreme_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue
            r0 = float(feats["rsi"].iloc[j]) if "rsi" in feats.columns else float("nan")
            if not np.isfinite(r0):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue

            favor_rsi = float(r0) if side_s.iloc[i] == "SHORT" else float(100.0 - r0)
            b0 = int(
                np.select(
                    [favor_rsi <= oversold, favor_rsi <= 50.0, favor_rsi < overbought],
                    [0, 1, 2],
                    default=3,
                )
            )
            e0 = int(favor_rsi >= overbought)

            bucket_vals.append(float(b0))
            extreme_vals.append(float(e0))
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["rsi_basic_favor_bucket_1h"] = bucket_vals
        dfm["rsi_basic_favor_extreme_1h"] = extreme_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "rsi_basic_favor_bucket_1h",
                    "rsi_basic_favor_extreme_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["rsi_basic_favor_bucket_1h", "rsi_basic_favor_extreme_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "rsi_basic_favor_bucket_1h",
            "rsi_basic_favor_extreme_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["rsi_basic_favor_bucket_1h", "rsi_basic_favor_extreme_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b67_cci_basic_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    cci_n: int = 20,
    cci_level: float = 100.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_csv = out_dir / f"b67_bucket_stats_{date_tag}_v1.csv"
    out_sum = out_dir / f"b67_feature_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b67_coverage_{date_tag}_v1.csv"
    out_corr = out_dir / f"b67_spearman_corr_{date_tag}_v1.csv"

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    bucket_rows: List[Dict[str, object]] = []
    cov_rows: List[Dict[str, object]] = []
    pooled_frames: List[pd.DataFrame] = []

    eps = 1e-12
    cci_n = int(cci_n)
    cci_level = float(cci_level)

    def _compute_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        h = pd.to_numeric(d1["high"], errors="coerce").astype(float)
        l = pd.to_numeric(d1["low"], errors="coerce").astype(float)
        c = pd.to_numeric(d1["close"], errors="coerce").astype(float)
        tp = ((h + l + c) / 3.0).astype(float)
        sma = tp.rolling(cci_n, min_periods=max(5, cci_n // 2)).mean()
        md = (tp - sma).abs().rolling(cci_n, min_periods=max(5, cci_n // 2)).mean()
        cci = ((tp - sma) / (0.015 * (md + eps))).astype(float)
        d1_fields = pd.DataFrame({"cci": cci}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        a1d["cci"] = pd.to_numeric(a1d["cci"], errors="coerce")
        return a1d

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        feat_cols = ["entry_score", "e1_break_strength_atr"]
        try:
            merged = _trade_level_merged_for_features(trades_csv, p0_sweep_dir, feat_cols)
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if merged.empty:
            continue

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None
        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz=None)
        except Exception:
            ohlc = pd.DataFrame()
        if ohlc.empty:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": str(profile).strip(),
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        feats = _compute_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        entry_ns = entry_dt.astype("int64")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        picked = 0
        bucket_vals: List[float] = []
        extreme_vals: List[float] = []

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            if pd.isna(en):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue
            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            if not (0 <= j < int(len(ts_ns))):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue
            c0 = float(feats["cci"].iloc[j]) if "cci" in feats.columns else float("nan")
            if not np.isfinite(c0):
                bucket_vals.append(float("nan"))
                extreme_vals.append(float("nan"))
                continue

            favor = float(c0) if side_s.iloc[i] == "SHORT" else float(-c0)
            b0 = int(
                np.select(
                    [favor <= -cci_level, favor <= 0.0, favor < cci_level],
                    [0, 1, 2],
                    default=3,
                )
            )
            e0 = int(favor >= cci_level)
            bucket_vals.append(float(b0))
            extreme_vals.append(float(e0))
            picked += 1

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": str(profile).strip(),
                "entries": float(len(merged)),
                "priced": float(picked),
                "priced_pct": float(picked) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        dfm = merged.copy()
        dfm["cci_basic_favor_bucket_1h"] = bucket_vals
        dfm["cci_basic_favor_extreme_1h"] = extreme_vals

        pooled_frames.append(
            dfm[
                [
                    "trade_pnl",
                    "cci_basic_favor_bucket_1h",
                    "cci_basic_favor_extreme_1h",
                    "entry_score",
                    "e1_break_strength_atr",
                ]
            ].copy()
        )

        for feat in ["cci_basic_favor_bucket_1h", "cci_basic_favor_extreme_1h"]:
            x_num = pd.to_numeric(dfm[feat], errors="coerce")
            m = x_num.notna()
            if int(m.sum()) < 20:
                continue
            dff = dfm[m].copy()
            dff["_x"] = x_num[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_bucket_rows(
                    bucket_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=str(profile).strip(),
                    feature=feat,
                    scheme="code4",
                    bucket_id=f"code4={int(v)}",
                    bucket_range=f"code4={int(v)}",
                    g=g,
                )

    stats_df = pd.DataFrame(bucket_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_csv, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")

    pooled = pd.concat(pooled_frames, ignore_index=True) if pooled_frames else pd.DataFrame()
    if pooled.empty:
        pd.DataFrame(columns=["scope", "split", "x", "y", "spearman", "n"]).to_csv(out_corr, index=False, encoding="utf-8-sig")
    else:
        for col in [
            "trade_pnl",
            "cci_basic_favor_bucket_1h",
            "cci_basic_favor_extreme_1h",
            "entry_score",
            "e1_break_strength_atr",
        ]:
            if col in pooled.columns:
                pooled[col] = pd.to_numeric(pooled[col], errors="coerce")
        rows = []
        for x in ["cci_basic_favor_bucket_1h", "cci_basic_favor_extreme_1h"]:
            for y in ["trade_pnl", "entry_score", "e1_break_strength_atr"]:
                rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "x": x,
                        "y": y,
                        "spearman": _safe_spearman_corr(pooled[x], pooled[y]),
                        "n": float(pooled[[x, y]].dropna().shape[0]),
                    }
                )
        pd.DataFrame(rows).to_csv(out_corr, index=False, encoding="utf-8-sig")

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    summ_rows: List[Dict[str, object]] = []
    if not stats_df.empty:
        for (feat, scheme), sub in stats_df.groupby(["feature", "scheme"], sort=True):
            if str(scheme) != "code4":
                continue
            sub2 = sub.copy()
            sub2["_code"] = sub2["bucket"].map(_code4_idx)
            sub2 = sub2[sub2["_code"].notna()].copy()
            if sub2.empty:
                continue
            sub2["_code"] = sub2["_code"].astype(int)
            if int(sub2["_code"].nunique()) < 2:
                continue
            lo = sub2.loc[sub2["_code"].idxmin()]
            hi = sub2.loc[sub2["_code"].idxmax()]
            summ_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_trades": float(pd.to_numeric(sub2["n_trades"], errors="coerce").sum()),
                    "top_minus_bot_avg_pnl": float(pd.to_numeric(hi["avg_pnl"], errors="coerce") - pd.to_numeric(lo["avg_pnl"], errors="coerce")),
                }
            )
    summary_df = pd.DataFrame(summ_rows)
    if not summary_df.empty:
        summary_df = summary_df.sort_values(["top_minus_bot_avg_pnl"], ascending=False, kind="mergesort").reset_index(drop=True)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"BUCKETS": out_csv, "SUMMARY": out_sum, "COVERAGE": out_cov, "CORR": out_corr}


def run_b68_osc_mae_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 50.0,
    profile_merge: bool = False,
    date_tag: str,
    rsi_n: int = 14,
    rsi_oversold: float = 30.0,
    rsi_overbought: float = 70.0,
    cci_n: int = 20,
    cci_level: float = 100.0,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_stats = out_dir / f"b68_mae_bucket_stats_{date_tag}_v1.csv"
    out_pairs = out_dir / f"b68_mae_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b68_mae_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b68_mae_coverage_{date_tag}_v1.csv"

    eps = 1e-12
    min_n = float(min_n)
    rsi_n = int(rsi_n)
    rsi_oversold = float(rsi_oversold)
    rsi_overbought = float(rsi_overbought)
    cci_n = int(cci_n)
    cci_level = float(cci_level)

    def _rsi(close: pd.Series, n: int) -> pd.Series:
        c = pd.to_numeric(close, errors="coerce").astype(float)
        d = c.diff()
        gain = d.clip(lower=0.0)
        loss = (-d).clip(lower=0.0)
        alpha = 1.0 / float(max(1, int(n)))
        avg_gain = gain.ewm(alpha=alpha, adjust=False, min_periods=max(2, int(n))).mean()
        avg_loss = loss.ewm(alpha=alpha, adjust=False, min_periods=max(2, int(n))).mean()
        rs = avg_gain / (avg_loss + eps)
        rsi = 100.0 - (100.0 / (1.0 + rs))
        rsi = rsi.where((avg_gain + avg_loss) > 0.0)
        return rsi

    def _compute_entry_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        rsi1d = _rsi(d1["close"], rsi_n)
        h = pd.to_numeric(d1["high"], errors="coerce").astype(float)
        l = pd.to_numeric(d1["low"], errors="coerce").astype(float)
        c = pd.to_numeric(d1["close"], errors="coerce").astype(float)
        tp = ((h + l + c) / 3.0).astype(float)
        sma = tp.rolling(cci_n, min_periods=max(5, cci_n // 2)).mean()
        md = (tp - sma).abs().rolling(cci_n, min_periods=max(5, cci_n // 2)).mean()
        cci = ((tp - sma) / (0.015 * (md + eps))).astype(float)
        d1_fields = pd.DataFrame({"rsi": rsi1d, "cci": cci}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        a1d["rsi"] = pd.to_numeric(a1d["rsi"], errors="coerce")
        a1d["cci"] = pd.to_numeric(a1d["cci"], errors="coerce")
        return a1d

    def _add_stat(
        rows: List[Dict[str, object]],
        *,
        symbol: str,
        split: str,
        profile: str,
        feature: str,
        scheme: str,
        bucket: str,
        g: pd.DataFrame,
    ) -> None:
        n = int(len(g))
        if n <= 0:
            return
        mae = pd.to_numeric(g.get("trade_mae_atr", pd.Series(index=g.index)), errors="coerce")
        mfe = pd.to_numeric(g.get("trade_mfe_atr", pd.Series(index=g.index)), errors="coerce")
        m_mae = mae.notna()
        m_mfe = mfe.notna()
        rows.append(
            {
                "symbol": symbol,
                "split": split,
                "profile": profile,
                "feature": feature,
                "scheme": scheme,
                "bucket": bucket,
                "n_trades": float(n),
                "win_rate": float(pd.to_numeric(g["win"], errors="coerce").mean()),
                "avg_pnl": float(pd.to_numeric(g["trade_pnl"], errors="coerce").mean()),
                "stop_loss_rate": float(pd.to_numeric(g["stop_loss_any"], errors="coerce").mean()),
                "tp2_rate": float(pd.to_numeric(g["tp2_any"], errors="coerce").mean()),
                "hold_hours_median": float(pd.to_numeric(g["hold_hours"], errors="coerce").median()),
                "mae_atr_mean": float(mae[m_mae].mean()) if bool(m_mae.any()) else float("nan"),
                "mae_atr_p90": float(mae[m_mae].quantile(0.90)) if bool(m_mae.any()) else float("nan"),
                "mfe_atr_mean": float(mfe[m_mfe].mean()) if bool(m_mfe.any()) else float("nan"),
                "mfe_atr_p90": float(mfe[m_mfe].quantile(0.90)) if bool(m_mfe.any()) else float("nan"),
                "mae_cov": float(m_mae.mean()) if n else float("nan"),
            }
        )

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    cov_rows: List[Dict[str, object]] = []
    stat_rows: List[Dict[str, object]] = []
    pair_rows: List[Dict[str, object]] = []

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        need_cols = ["atr"]
        try:
            df = pd.read_csv(
                trades_csv,
                dtype=str,
                encoding="utf-8-sig",
                usecols=lambda c: c
                in {
                    "entry_time",
                    "side",
                    "entry",
                    "signal",
                    "exit_time",
                    "pnl",
                    "reason",
                    *need_cols,
                },
            )
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if df.empty or "entry_time" not in df.columns:
            continue

        for c in ["signal", "reason", "side", "entry", "exit_time", "pnl"]:
            if c not in df.columns:
                df[c] = ""
        for c in need_cols:
            if c not in df.columns:
                df[c] = ""
        df = df.fillna("").astype(str)

        key_cols = ["entry_time", "side", "entry"]
        is_entry = df["signal"].astype(str).str.strip().ne("")
        entry_rows = df[is_entry].drop_duplicates(subset=key_cols, keep="last").copy()
        if entry_rows.empty:
            continue

        pnl = pd.to_numeric(df["pnl"], errors="coerce")
        pnl0 = pnl.fillna(0.0)
        reason_s = df["reason"].astype(str).str.strip()
        is_tp2 = reason_s.isin(["tp_cam_r2", "tp_cam_s2"])
        is_stop = reason_s.str.contains("stop", case=False, na=False)
        is_stop_loss = is_stop & (pnl0 < 0.0)

        entry_dt = pd.to_datetime(df["entry_time"], utc=True, errors="coerce")
        exit_dt = pd.to_datetime(df["exit_time"], utc=True, errors="coerce")

        pnl_sum = pnl.groupby([df[k] for k in key_cols], sort=False).sum(min_count=1)
        tp2_any = is_tp2.groupby([df[k] for k in key_cols], sort=False).any()
        stop_loss_any = is_stop_loss.groupby([df[k] for k in key_cols], sort=False).any()
        max_exit = exit_dt.groupby([df[k] for k in key_cols], sort=False).max()
        min_entry = entry_dt.groupby([df[k] for k in key_cols], sort=False).min()

        tl = pd.DataFrame(
            {
                "entry_time": pnl_sum.index.get_level_values(0).astype(str),
                "side": pnl_sum.index.get_level_values(1).astype(str),
                "entry": pnl_sum.index.get_level_values(2).astype(str),
                "trade_pnl": pnl_sum.to_numpy(),
                "tp2_any": tp2_any.to_numpy(dtype=bool),
                "stop_loss_any": stop_loss_any.to_numpy(dtype=bool),
                "max_exit_time": max_exit.to_numpy(),
                "min_entry_time": min_entry.to_numpy(),
            }
        ).copy()
        tl["win"] = pd.to_numeric(tl["trade_pnl"], errors="coerce").fillna(0.0) > 0.0
        hold = pd.to_datetime(tl["max_exit_time"], utc=True, errors="coerce") - pd.to_datetime(tl["min_entry_time"], utc=True, errors="coerce")
        tl["hold_hours"] = hold.dt.total_seconds() / 3600.0

        feats = entry_rows[key_cols + [c for c in need_cols if c in entry_rows.columns]].copy()
        merged = tl.merge(feats, on=key_cols, how="left")
        if merged.empty:
            continue

        prof = "A_all" if profile_merge else str(profile).strip()

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None

        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof,
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        ohlc = load_ohlcv_1h(csv_path, tz=None)
        if ohlc.empty or "high" not in ohlc.columns or "low" not in ohlc.columns:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof,
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        entry_fields = _compute_entry_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")
        low_arr = pd.to_numeric(ohlc["low"], errors="coerce").to_numpy(dtype=float)
        high_arr = pd.to_numeric(ohlc["high"], errors="coerce").to_numpy(dtype=float)

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        hold_td = pd.to_timedelta(pd.to_numeric(merged.get("hold_hours", pd.Series(index=merged.index)), errors="coerce"), unit="h")
        exit_dt = entry_dt + hold_td
        entry_ns = entry_dt.astype("int64")
        exit_ns = exit_dt.astype("int64")
        entry_px = pd.to_numeric(merged["entry"], errors="coerce")
        atr0 = pd.to_numeric(merged.get("atr", pd.Series(index=merged.index)), errors="coerce")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        mae_atr: List[float] = []
        mfe_atr: List[float] = []
        rsi_bucket: List[float] = []
        cci_bucket: List[float] = []
        priced = 0

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            ex = exit_ns.iloc[i]
            ep = entry_px.iloc[i]
            a0 = atr0.iloc[i]
            if pd.isna(en) or pd.isna(ex) or pd.isna(ep) or pd.isna(a0) or float(a0) <= 0.0:
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                rsi_bucket.append(float("nan"))
                cci_bucket.append(float("nan"))
                continue
            si = int(np.searchsorted(ts_ns, int(en), side="left"))
            ei = int(np.searchsorted(ts_ns, int(ex), side="right"))
            if si < 0:
                si = 0
            if ei > int(len(ts_ns)):
                ei = int(len(ts_ns))
            if not (0 <= si < ei <= int(len(ts_ns))):
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                rsi_bucket.append(float("nan"))
                cci_bucket.append(float("nan"))
                continue
            lo = float(np.nanmin(low_arr[si:ei]))
            hi = float(np.nanmax(high_arr[si:ei]))
            if not (np.isfinite(lo) and np.isfinite(hi)):
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                rsi_bucket.append(float("nan"))
                cci_bucket.append(float("nan"))
                continue

            s0 = side_s.iloc[i]
            if s0 == "SHORT":
                mae = (hi - float(ep)) / float(a0)
                mfe = (float(ep) - lo) / float(a0)
            else:
                mae = (float(ep) - lo) / float(a0)
                mfe = (hi - float(ep)) / float(a0)

            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            r0 = float(entry_fields["rsi"].iloc[j]) if ("rsi" in entry_fields.columns and 0 <= j < int(len(entry_fields))) else float("nan")
            c0 = float(entry_fields["cci"].iloc[j]) if ("cci" in entry_fields.columns and 0 <= j < int(len(entry_fields))) else float("nan")

            if not (np.isfinite(r0) and np.isfinite(c0)):
                mae_atr.append(float("nan"))
                mfe_atr.append(float("nan"))
                rsi_bucket.append(float("nan"))
                cci_bucket.append(float("nan"))
                continue

            favor_rsi = float(r0) if s0 == "SHORT" else float(100.0 - r0)
            b_rsi = int(
                np.select(
                    [favor_rsi <= rsi_oversold, favor_rsi <= 50.0, favor_rsi < rsi_overbought],
                    [0, 1, 2],
                    default=3,
                )
            )
            favor_cci = float(c0) if s0 == "SHORT" else float(-c0)
            b_cci = int(
                np.select(
                    [favor_cci <= -cci_level, favor_cci <= 0.0, favor_cci < cci_level],
                    [0, 1, 2],
                    default=3,
                )
            )

            mae_atr.append(float(mae))
            mfe_atr.append(float(mfe))
            rsi_bucket.append(float(b_rsi))
            cci_bucket.append(float(b_cci))
            priced += 1

        merged = merged.copy()
        merged["trade_mae_atr"] = mae_atr
        merged["trade_mfe_atr"] = mfe_atr
        merged["rsi_basic_favor_bucket_1h"] = rsi_bucket
        merged["cci_basic_favor_bucket_1h"] = cci_bucket

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": prof,
                "entries": float(len(merged)),
                "priced": float(priced),
                "priced_pct": float(priced) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        merged["profile"] = prof

        for feat in ["rsi_basic_favor_bucket_1h", "cci_basic_favor_bucket_1h"]:
            x = pd.to_numeric(merged[feat], errors="coerce")
            m = x.notna() & pd.to_numeric(merged["trade_mae_atr"], errors="coerce").notna()
            if int(m.sum()) < int(max(2.0 * min_n, 20.0)):
                continue
            dff = merged[m].copy()
            dff["_x"] = x[m].astype(float).to_numpy()
            for v, g in dff.groupby("_x", sort=True):
                _add_stat(
                    stat_rows,
                    symbol=sym_u,
                    split=str(split).strip(),
                    profile=prof,
                    feature=feat,
                    scheme="code4",
                    bucket=f"code4={int(v)}",
                    g=g,
                )

            cnt = dff.groupby("_x", sort=True).size()
            ok = cnt[cnt >= int(min_n)]
            if int(ok.size) >= 2:
                lo_code = float(ok.index.min())
                hi_code = float(ok.index.max())
                g0 = dff[dff["_x"] == lo_code].copy()
                g3 = dff[dff["_x"] == hi_code].copy()
                n0 = int(len(g0))
                n3 = int(len(g3))
                mae0 = float(pd.to_numeric(g0["trade_mae_atr"], errors="coerce").mean())
                mae3 = float(pd.to_numeric(g3["trade_mae_atr"], errors="coerce").mean())
                sl0 = float(pd.to_numeric(g0["stop_loss_any"], errors="coerce").mean())
                sl3 = float(pd.to_numeric(g3["stop_loss_any"], errors="coerce").mean())
                pnl0 = float(pd.to_numeric(g0["trade_pnl"], errors="coerce").mean())
                pnl3 = float(pd.to_numeric(g3["trade_pnl"], errors="coerce").mean())
                pair_rows.append(
                    {
                        "scope": scope_id,
                        "split": str(split_filter).strip(),
                        "symbol": sym_u,
                        "profile": prof,
                        "feature": feat,
                        "scheme": "code4",
                        "group_a": f"code4={int(lo_code)}",
                        "group_b": f"code4={int(hi_code)}",
                        "n_a": float(n0),
                        "n_b": float(n3),
                        "mae_atr_mean_a": mae0,
                        "mae_atr_mean_b": mae3,
                        "stop_loss_rate_a": sl0,
                        "stop_loss_rate_b": sl3,
                        "avg_pnl_a": pnl0,
                        "avg_pnl_b": pnl3,
                        "delta_mae_atr_mean": float(mae3 - mae0),
                        "delta_stop_loss_rate": float(sl3 - sl0),
                        "delta_avg_pnl": float(pnl3 - pnl0),
                        "mae_better": float(mae3 < mae0),
                        "stop_loss_better": float(sl3 < sl0),
                        "pnl_better": float(pnl3 > pnl0),
                        "both_mae_stop_better": float((mae3 < mae0) and (sl3 < sl0)),
                    }
                )

    stats_df = pd.DataFrame(stat_rows)
    if not stats_df.empty:
        stats_df.insert(0, "scope", scope_id)
    stats_df.to_csv(out_stats, index=False, encoding="utf-8-sig")
    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")
    pair_df = pd.DataFrame(pair_rows)
    if pair_df.empty:
        pair_df = pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "mae_atr_mean_a",
                "mae_atr_mean_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "delta_mae_atr_mean",
                "delta_stop_loss_rate",
                "delta_avg_pnl",
                "mae_better",
                "stop_loss_better",
                "pnl_better",
                "both_mae_stop_better",
            ]
        )
    pair_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    sum_rows: List[Dict[str, object]] = []
    if not pair_df.empty:
        for (feat, scheme), sub in pair_df.groupby(["feature", "scheme"], sort=True):
            m = pd.to_numeric(sub["n_a"], errors="coerce").notna() & pd.to_numeric(sub["n_b"], errors="coerce").notna()
            sub2 = sub[m].copy()
            n_pairs = float(len(sub2))
            if n_pairs <= 0:
                continue
            sum_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": n_pairs,
                    "n_sufficient": n_pairs,
                    "frac_mae_better": float(pd.to_numeric(sub2["mae_better"], errors="coerce").mean()),
                    "frac_stop_loss_better": float(pd.to_numeric(sub2["stop_loss_better"], errors="coerce").mean()),
                    "frac_pnl_better": float(pd.to_numeric(sub2["pnl_better"], errors="coerce").mean()),
                    "frac_both_mae_stop": float(pd.to_numeric(sub2["both_mae_stop_better"], errors="coerce").mean()),
                }
            )
    sum_df = pd.DataFrame(sum_rows)
    if sum_df.empty:
        sum_df = pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_mae_better",
                "frac_stop_loss_better",
                "frac_pnl_better",
                "frac_both_mae_stop",
            ]
        )
    sum_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"STATS": out_stats, "PAIRS": out_pairs, "SUMMARY": out_sum, "COVERAGE": out_cov}


def run_b69_rsi_filter_sim_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
    rsi_n: int = 14,
    oversold: float = 30.0,
    overbought: float = 70.0,
    drop_bucket: int = 3,
    keep_buckets: str = "",
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_pairs = out_dir / f"b69_filter_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b69_filter_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b69_filter_coverage_{date_tag}_v1.csv"

    eps = 1e-12
    min_n = float(min_n)
    rsi_n = int(rsi_n)
    oversold = float(oversold)
    overbought = float(overbought)
    drop_bucket = int(drop_bucket)
    keep_buckets = str(keep_buckets or "").strip()
    keep_set: Set[int] = set()
    if keep_buckets:
        for p in re.split(r"[,\s]+", keep_buckets):
            p2 = str(p).strip()
            if not p2:
                continue
            try:
                keep_set.add(int(p2))
            except Exception:
                continue

    def _rsi(close: pd.Series, n: int) -> pd.Series:
        c = pd.to_numeric(close, errors="coerce").astype(float)
        d = c.diff()
        gain = d.clip(lower=0.0)
        loss = (-d).clip(lower=0.0)
        alpha = 1.0 / float(max(1, int(n)))
        avg_gain = gain.ewm(alpha=alpha, adjust=False, min_periods=max(2, int(n))).mean()
        avg_loss = loss.ewm(alpha=alpha, adjust=False, min_periods=max(2, int(n))).mean()
        rs = avg_gain / (avg_loss + eps)
        rsi = 100.0 - (100.0 / (1.0 + rs))
        rsi = rsi.where((avg_gain + avg_loss) > 0.0)
        return rsi

    def _compute_entry_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        rsi1d = _rsi(d1["close"], rsi_n)
        d1_fields = pd.DataFrame({"rsi": rsi1d}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        a1d["rsi"] = pd.to_numeric(a1d["rsi"], errors="coerce")
        return a1d

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    cov_rows: List[Dict[str, object]] = []
    pair_rows: List[Dict[str, object]] = []

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        need_cols = ["atr"]
        try:
            df = pd.read_csv(
                trades_csv,
                dtype=str,
                encoding="utf-8-sig",
                usecols=lambda c: c
                in {
                    "entry_time",
                    "side",
                    "entry",
                    "signal",
                    "exit_time",
                    "pnl",
                    "reason",
                    *need_cols,
                },
            )
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if df.empty or "entry_time" not in df.columns:
            continue

        for c in ["signal", "reason", "side", "entry", "exit_time", "pnl"]:
            if c not in df.columns:
                df[c] = ""
        for c in need_cols:
            if c not in df.columns:
                df[c] = ""
        df = df.fillna("").astype(str)

        key_cols = ["entry_time", "side", "entry"]
        is_entry = df["signal"].astype(str).str.strip().ne("")
        entry_rows = df[is_entry].drop_duplicates(subset=key_cols, keep="last").copy()
        if entry_rows.empty:
            continue

        pnl = pd.to_numeric(df["pnl"], errors="coerce")
        pnl0 = pnl.fillna(0.0)
        reason_s = df["reason"].astype(str).str.strip()
        is_stop = reason_s.str.contains("stop", case=False, na=False)
        is_stop_loss = is_stop & (pnl0 < 0.0)

        entry_dt = pd.to_datetime(df["entry_time"], utc=True, errors="coerce")
        exit_dt = pd.to_datetime(df["exit_time"], utc=True, errors="coerce")

        pnl_sum = pnl.groupby([df[k] for k in key_cols], sort=False).sum(min_count=1)
        stop_loss_any = is_stop_loss.groupby([df[k] for k in key_cols], sort=False).any()
        max_exit = exit_dt.groupby([df[k] for k in key_cols], sort=False).max()
        min_entry = entry_dt.groupby([df[k] for k in key_cols], sort=False).min()

        tl = pd.DataFrame(
            {
                "entry_time": pnl_sum.index.get_level_values(0).astype(str),
                "side": pnl_sum.index.get_level_values(1).astype(str),
                "entry": pnl_sum.index.get_level_values(2).astype(str),
                "trade_pnl": pnl_sum.to_numpy(),
                "stop_loss_any": stop_loss_any.to_numpy(dtype=bool),
                "max_exit_time": max_exit.to_numpy(),
                "min_entry_time": min_entry.to_numpy(),
            }
        ).copy()
        hold = pd.to_datetime(tl["max_exit_time"], utc=True, errors="coerce") - pd.to_datetime(tl["min_entry_time"], utc=True, errors="coerce")
        tl["hold_hours"] = hold.dt.total_seconds() / 3600.0

        feats = entry_rows[key_cols + [c for c in need_cols if c in entry_rows.columns]].copy()
        merged = tl.merge(feats, on=key_cols, how="left")
        if merged.empty:
            continue

        prof = "A_all" if profile_merge else str(profile).strip()

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None

        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof,
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        ohlc = load_ohlcv_1h(csv_path, tz=None)
        if ohlc.empty or "high" not in ohlc.columns or "low" not in ohlc.columns:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof,
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        entry_fields = _compute_entry_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")
        low_arr = pd.to_numeric(ohlc["low"], errors="coerce").to_numpy(dtype=float)
        high_arr = pd.to_numeric(ohlc["high"], errors="coerce").to_numpy(dtype=float)

        entry_dt = pd.to_datetime(merged["entry_time"], utc=True, errors="coerce")
        hold_td = pd.to_timedelta(pd.to_numeric(merged.get("hold_hours", pd.Series(index=merged.index)), errors="coerce"), unit="h")
        exit_dt = entry_dt + hold_td
        entry_ns = entry_dt.astype("int64")
        exit_ns = exit_dt.astype("int64")
        entry_px = pd.to_numeric(merged["entry"], errors="coerce")
        atr0 = pd.to_numeric(merged.get("atr", pd.Series(index=merged.index)), errors="coerce")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        mae_atr: List[float] = []
        bucket_vals: List[float] = []
        priced = 0

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            ex = exit_ns.iloc[i]
            ep = entry_px.iloc[i]
            a0 = atr0.iloc[i]
            if pd.isna(en) or pd.isna(ex) or pd.isna(ep) or pd.isna(a0) or float(a0) <= 0.0:
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue
            si = int(np.searchsorted(ts_ns, int(en), side="left"))
            ei = int(np.searchsorted(ts_ns, int(ex), side="right"))
            if si < 0:
                si = 0
            if ei > int(len(ts_ns)):
                ei = int(len(ts_ns))
            if not (0 <= si < ei <= int(len(ts_ns))):
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue
            lo = float(np.nanmin(low_arr[si:ei]))
            hi = float(np.nanmax(high_arr[si:ei]))
            if not (np.isfinite(lo) and np.isfinite(hi)):
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue

            s0 = side_s.iloc[i]
            if s0 == "SHORT":
                mae = (hi - float(ep)) / float(a0)
            else:
                mae = (float(ep) - lo) / float(a0)

            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            r0 = float(entry_fields["rsi"].iloc[j]) if ("rsi" in entry_fields.columns and 0 <= j < int(len(entry_fields))) else float("nan")
            if not np.isfinite(r0):
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue

            favor_rsi = float(r0) if s0 == "SHORT" else float(100.0 - r0)
            b0 = int(
                np.select(
                    [favor_rsi <= oversold, favor_rsi <= 50.0, favor_rsi < overbought],
                    [0, 1, 2],
                    default=3,
                )
            )
            mae_atr.append(float(mae))
            bucket_vals.append(float(b0))
            priced += 1

        merged = merged.copy()
        merged["profile"] = prof
        merged["trade_mae_atr"] = mae_atr
        merged["rsi_basic_favor_bucket_1h"] = bucket_vals

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": prof,
                "entries": float(len(merged)),
                "priced": float(priced),
                "priced_pct": float(priced) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        x = pd.to_numeric(merged["rsi_basic_favor_bucket_1h"], errors="coerce")
        mae = pd.to_numeric(merged["trade_mae_atr"], errors="coerce")
        m = x.notna() & mae.notna()
        dff = merged[m].copy()
        if dff.empty:
            continue

        if keep_set:
            keep = dff[dff["rsi_basic_favor_bucket_1h"].astype(int).isin(sorted(keep_set))].copy()
            drop = dff[~dff["rsi_basic_favor_bucket_1h"].astype(int).isin(sorted(keep_set))].copy()
        else:
            keep = dff[dff["rsi_basic_favor_bucket_1h"].astype(float) != float(drop_bucket)].copy()
            drop = dff[dff["rsi_basic_favor_bucket_1h"].astype(float) == float(drop_bucket)].copy()
        if int(len(keep)) < int(min_n) or int(len(drop)) < int(min_n):
            continue

        def _agg(g: pd.DataFrame) -> Dict[str, float]:
            return {
                "n": float(len(g)),
                "avg_pnl": float(pd.to_numeric(g["trade_pnl"], errors="coerce").mean()),
                "stop_loss_rate": float(pd.to_numeric(g["stop_loss_any"], errors="coerce").mean()),
                "mae_atr_mean": float(pd.to_numeric(g["trade_mae_atr"], errors="coerce").mean()),
                "hold_hours_median": float(pd.to_numeric(g["hold_hours"], errors="coerce").median()),
            }

        a = _agg(dff)
        b = _agg(keep)

        pair_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": prof,
                "feature": "rsi_basic_favor_bucket_1h",
                "drop_bucket": int(drop_bucket),
                "keep_buckets": keep_buckets,
                "n_total": a["n"],
                "n_keep": b["n"],
                "keep_pct": float(b["n"] / a["n"]) if a["n"] else float("nan"),
                "avg_pnl_total": a["avg_pnl"],
                "avg_pnl_keep": b["avg_pnl"],
                "stop_loss_rate_total": a["stop_loss_rate"],
                "stop_loss_rate_keep": b["stop_loss_rate"],
                "mae_atr_mean_total": a["mae_atr_mean"],
                "mae_atr_mean_keep": b["mae_atr_mean"],
                "hold_hours_median_total": a["hold_hours_median"],
                "hold_hours_median_keep": b["hold_hours_median"],
                "delta_avg_pnl": float(b["avg_pnl"] - a["avg_pnl"]),
                "delta_stop_loss_rate": float(b["stop_loss_rate"] - a["stop_loss_rate"]),
                "delta_mae_atr_mean": float(b["mae_atr_mean"] - a["mae_atr_mean"]),
                "pnl_better": float(b["avg_pnl"] > a["avg_pnl"]),
                "stop_loss_better": float(b["stop_loss_rate"] < a["stop_loss_rate"]),
                "mae_better": float(b["mae_atr_mean"] < a["mae_atr_mean"]),
                "both_risk_better": float((b["stop_loss_rate"] < a["stop_loss_rate"]) and (b["mae_atr_mean"] < a["mae_atr_mean"])),
            }
        )

    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")
    pairs_df = pd.DataFrame(pair_rows)
    if pairs_df.empty:
        pairs_df = pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "drop_bucket",
                "keep_buckets",
                "n_total",
                "n_keep",
                "keep_pct",
                "avg_pnl_total",
                "avg_pnl_keep",
                "stop_loss_rate_total",
                "stop_loss_rate_keep",
                "mae_atr_mean_total",
                "mae_atr_mean_keep",
                "hold_hours_median_total",
                "hold_hours_median_keep",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_mae_atr_mean",
                "pnl_better",
                "stop_loss_better",
                "mae_better",
                "both_risk_better",
            ]
        )
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    sum_rows: List[Dict[str, object]] = []
    if not pairs_df.empty:
        sum_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "feature": "rsi_basic_favor_bucket_1h",
                "drop_bucket": int(drop_bucket),
                "keep_buckets": keep_buckets,
                "n_pairs": float(len(pairs_df)),
                "frac_pnl_better": float(pd.to_numeric(pairs_df["pnl_better"], errors="coerce").mean()),
                "frac_stop_loss_better": float(pd.to_numeric(pairs_df["stop_loss_better"], errors="coerce").mean()),
                "frac_mae_better": float(pd.to_numeric(pairs_df["mae_better"], errors="coerce").mean()),
                "frac_both_risk_better": float(pd.to_numeric(pairs_df["both_risk_better"], errors="coerce").mean()),
                "median_keep_pct": float(pd.to_numeric(pairs_df["keep_pct"], errors="coerce").median()),
            }
        )
    sum_df = pd.DataFrame(sum_rows)
    if sum_df.empty:
        sum_df = pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "drop_bucket",
                "keep_buckets",
                "n_pairs",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_mae_better",
                "frac_both_risk_better",
                "median_keep_pct",
            ]
        )
    sum_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum, "COVERAGE": out_cov}


def run_b71_rsi_truegate_sweep(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    date_tag: str,
    min_window_days: int = 365,
    drop_bucket: int = 0,
    p_base: Params,
    c: Optional[Config] = None,
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    split_id = str(split_filter).strip()
    min_window_days = int(max(1, int(min_window_days)))
    drop_bucket = int(drop_bucket)

    out_detail = out_dir / f"b71_truegate_detail_{date_tag}_v1.csv"
    out_agg = out_dir / f"b71_truegate_agg_{date_tag}_v1.csv"

    base = Params(**{**Params().__dict__, **p_base.__dict__, "enable_entry_rsi_bucket_gate": False})
    gate = Params(**{**Params().__dict__, **p_base.__dict__, "enable_entry_rsi_bucket_gate": True, "entry_rsi_drop_bucket": drop_bucket})

    rows: List[Dict[str, object]] = []
    for sym_u in sorted((allow_syms if allow_syms else set([p.stem.replace("_1h", "").upper() for p in csv_dir.glob("*_1h.csv")]))):
        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            continue
        if csv_path is None or not csv_path.exists():
            continue

        try:
            ohlc = load_ohlcv_1h(csv_path, tz="UTC")
        except Exception:
            continue
        if ohlc.empty:
            continue

        start0 = ohlc.index.min()
        end0 = ohlc.index.max()
        if pd.isna(start0) or pd.isna(end0):
            continue

        if split_id == "since2022":
            anchor = pd.Timestamp("2022-01-01", tz=start0.tz)
            wf = start0 if start0 >= anchor else anchor
            wt = end0
        elif split_id == "pre2022":
            anchor = pd.Timestamp("2021-12-31", tz=start0.tz)
            wt = end0 if end0 <= anchor else anchor
            wf = start0
        else:
            wf = start0
            wt = end0

        if wf >= wt:
            continue
        window_days = int((wt - wf).total_seconds() // 86400)
        if window_days < min_window_days:
            continue

        df1h = ohlc[(ohlc.index >= wf) & (ohlc.index <= wt)].copy()
        if df1h.empty:
            continue
        df4h = resample_ohlcv(df1h, "4H")
        df1d = resample_ohlcv(df1h, "1D")
        trend = compute_trend_flags(df1h, df4h, df1d, base)
        df1h_atr = df1h.copy()
        df1h_atr["atr"] = atr(df1h_atr, base.atr_n)

        c1 = c or Config(timezone="UTC", symbol=sym_u)
        _, m0, _ = backtest_one(df1h_atr, trend, base, c1)
        _, m1, _ = backtest_one(df1h_atr, trend, gate, c1)

        base_trades = float(m0.get("trades", np.nan))
        gate_trades = float(m1.get("trades", np.nan))
        base_net = float(m0.get("net_pnl", np.nan))
        gate_net = float(m1.get("net_pnl", np.nan))
        base_dd = float(m0.get("final_max_drawdown_pct", np.nan))
        gate_dd = float(m1.get("final_max_drawdown_pct", np.nan))
        base_wr = float(m0.get("win_rate", np.nan))
        gate_wr = float(m1.get("win_rate", np.nan))

        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": sym_u,
                "window_from": wf.isoformat(),
                "window_to": wt.isoformat(),
                "window_days": float(window_days),
                "base_trades": base_trades,
                "base_net_pnl": base_net,
                "base_win_rate": base_wr,
                "base_final_max_dd_pct": base_dd,
                "gate_trades": gate_trades,
                "gate_net_pnl": gate_net,
                "gate_win_rate": gate_wr,
                "gate_final_max_dd_pct": gate_dd,
                "delta_trades": float(gate_trades - base_trades) if np.isfinite(base_trades) and np.isfinite(gate_trades) else np.nan,
                "delta_net_pnl": float(gate_net - base_net) if np.isfinite(base_net) and np.isfinite(gate_net) else np.nan,
                "delta_final_max_dd_pct": float(gate_dd - base_dd) if np.isfinite(base_dd) and np.isfinite(gate_dd) else np.nan,
            }
        )

    df = pd.DataFrame(rows)
    df.to_csv(out_detail, index=False, encoding="utf-8-sig")

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "drop_bucket",
                "symbols",
                "avg_base_net_pnl",
                "avg_gate_net_pnl",
                "avg_delta_net_pnl",
                "avg_base_trades",
                "avg_gate_trades",
                "avg_delta_trades",
                "avg_base_final_max_dd_pct",
                "avg_gate_final_max_dd_pct",
                "avg_delta_final_max_dd_pct",
            ]
        ).to_csv(out_agg, index=False, encoding="utf-8-sig")
        return {"DETAIL": out_detail, "AGG": out_agg}

    num = df.copy()
    for c2 in [
        "base_net_pnl",
        "gate_net_pnl",
        "delta_net_pnl",
        "base_trades",
        "gate_trades",
        "delta_trades",
        "base_final_max_dd_pct",
        "gate_final_max_dd_pct",
        "delta_final_max_dd_pct",
    ]:
        if c2 in num.columns:
            num[c2] = pd.to_numeric(num[c2], errors="coerce")

    agg = pd.DataFrame(
        [
            {
                "scope": scope_id,
                "split": split_id,
                "drop_bucket": float(drop_bucket),
                "symbols": float(len(num)),
                "avg_base_net_pnl": float(num["base_net_pnl"].mean()),
                "avg_gate_net_pnl": float(num["gate_net_pnl"].mean()),
                "avg_delta_net_pnl": float(num["delta_net_pnl"].mean()),
                "avg_base_trades": float(num["base_trades"].mean()),
                "avg_gate_trades": float(num["gate_trades"].mean()),
                "avg_delta_trades": float(num["delta_trades"].mean()),
                "avg_base_final_max_dd_pct": float(num["base_final_max_dd_pct"].mean()),
                "avg_gate_final_max_dd_pct": float(num["gate_final_max_dd_pct"].mean()),
                "avg_delta_final_max_dd_pct": float(num["delta_final_max_dd_pct"].mean()),
            }
        ]
    )
    agg.to_csv(out_agg, index=False, encoding="utf-8-sig")
    return {"DETAIL": out_detail, "AGG": out_agg}


def run_b70_cci_filter_sim_evidence(
    *,
    p0_sweep_dir: Path,
    csv_dir: Path,
    out_dir: Path,
    scope: str = "all",
    split_filter: str = "since2022",
    min_n: float = 20.0,
    profile_merge: bool = False,
    date_tag: str,
    cci_n: int = 20,
    cci_level: float = 100.0,
    drop_bucket: int = 3,
    keep_buckets: str = "",
) -> Dict[str, Path]:
    p0_sweep_dir = Path(p0_sweep_dir)
    csv_dir = Path(csv_dir)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    deploy_core = _find_latest_matching(p0_sweep_dir, "deploy_core_*.csv")
    deploy_observe = _find_latest_matching(p0_sweep_dir, "deploy_observe_*.csv")
    core_syms = set(_load_symbols_from_deploy(deploy_core))
    obs_syms = set(_load_symbols_from_deploy(deploy_observe))
    scope_l = scope.strip().lower()
    if scope_l in {"core6", "core"}:
        allow_syms = core_syms
        scope_id = "core6"
    elif scope_l in {"core_observe", "core+observe", "core6_observe7"}:
        allow_syms = core_syms | obs_syms
        scope_id = "core6_observe7"
    else:
        allow_syms = set()
        scope_id = "all"

    out_pairs = out_dir / f"b70_filter_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"b70_filter_summary_{date_tag}_v1.csv"
    out_cov = out_dir / f"b70_filter_coverage_{date_tag}_v1.csv"

    eps = 1e-12
    min_n = float(min_n)
    cci_n = int(cci_n)
    cci_level = float(cci_level)
    drop_bucket = int(drop_bucket)
    keep_buckets = str(keep_buckets or "").strip()
    keep_set: Set[int] = set()
    if keep_buckets:
        for p in re.split(r"[,\s]+", keep_buckets):
            p2 = str(p).strip()
            if not p2:
                continue
            try:
                keep_set.add(int(p2))
            except Exception:
                continue

    def _compute_entry_fields_1h(ohlc: pd.DataFrame) -> pd.DataFrame:
        d1 = resample_ohlcv(ohlc, "1D")
        if d1.empty:
            return pd.DataFrame(index=ohlc.index)
        h = pd.to_numeric(d1["high"], errors="coerce").astype(float)
        l = pd.to_numeric(d1["low"], errors="coerce").astype(float)
        c = pd.to_numeric(d1["close"], errors="coerce").astype(float)
        tp = ((h + l + c) / 3.0).astype(float)
        sma = tp.rolling(cci_n, min_periods=max(5, cci_n // 2)).mean()
        md = (tp - sma).abs().rolling(cci_n, min_periods=max(5, cci_n // 2)).mean()
        cci = ((tp - sma) / (0.015 * (md + eps))).astype(float)
        d1_fields = pd.DataFrame({"cci": cci}, index=d1.index)
        a1d = align_last_closed(d1_fields, ohlc.index)
        a1d["cci"] = pd.to_numeric(a1d["cci"], errors="coerce")
        return a1d

    files = _iter_trades_baseline_csvs(p0_sweep_dir)
    cov_rows: List[Dict[str, object]] = []
    pair_rows: List[Dict[str, object]] = []

    for trades_csv in files:
        symbol, split, profile = _extract_symbol_split_profile(trades_csv, p0_sweep_dir)
        sym_u = str(symbol).strip().upper()
        if allow_syms and sym_u not in allow_syms:
            continue
        if split_filter and str(split).strip() != str(split_filter).strip():
            continue

        need_cols = ["atr"]
        try:
            df = pd.read_csv(
                trades_csv,
                dtype=str,
                encoding="utf-8-sig",
                usecols=lambda c: c
                in {
                    "entry_time",
                    "side",
                    "entry",
                    "signal",
                    "exit_time",
                    "pnl",
                    "reason",
                    *need_cols,
                },
            )
        except pd.errors.EmptyDataError:
            continue
        except Exception:
            continue
        if df.empty or "entry_time" not in df.columns:
            continue

        for c in ["signal", "reason", "side", "entry", "exit_time", "pnl"]:
            if c not in df.columns:
                df[c] = ""
        for c in need_cols:
            if c not in df.columns:
                df[c] = ""
        df = df.fillna("").astype(str)

        key_cols = ["entry_time", "side", "entry"]
        is_entry = df["signal"].astype(str).str.strip().ne("")
        entry_rows = df[is_entry].drop_duplicates(subset=key_cols, keep="last").copy()
        if entry_rows.empty:
            continue

        pnl = pd.to_numeric(df["pnl"], errors="coerce")
        pnl0 = pnl.fillna(0.0)
        reason_s = df["reason"].astype(str).str.strip()
        is_stop = reason_s.str.contains("stop", case=False, na=False)
        is_stop_loss = is_stop & (pnl0 < 0.0)

        entry_dt = pd.to_datetime(df["entry_time"], utc=True, errors="coerce")
        exit_dt = pd.to_datetime(df["exit_time"], utc=True, errors="coerce")

        pnl_sum = pnl.groupby([df[k] for k in key_cols], sort=False).sum(min_count=1)
        stop_loss_any = is_stop_loss.groupby([df[k] for k in key_cols], sort=False).any()
        max_exit = exit_dt.groupby([df[k] for k in key_cols], sort=False).max()
        min_entry = entry_dt.groupby([df[k] for k in key_cols], sort=False).min()

        tl = pd.DataFrame(
            {
                "entry_time": pnl_sum.index.get_level_values(0).astype(str),
                "side": pnl_sum.index.get_level_values(1).astype(str),
                "entry": pnl_sum.index.get_level_values(2).astype(str),
                "trade_pnl": pnl_sum.to_numpy(),
                "stop_loss_any": stop_loss_any.to_numpy(dtype=bool),
                "max_exit_time": max_exit.to_numpy(),
                "min_entry_time": min_entry.to_numpy(),
            }
        ).copy()
        hold = pd.to_datetime(tl["max_exit_time"], utc=True, errors="coerce") - pd.to_datetime(tl["min_entry_time"], utc=True, errors="coerce")
        tl["hold_hours"] = hold.dt.total_seconds() / 3600.0

        feats = entry_rows[key_cols + [c for c in need_cols if c in entry_rows.columns]].copy()
        merged = tl.merge(feats, on=key_cols, how="left")
        if merged.empty:
            continue

        prof = "A_all" if profile_merge else str(profile).strip()

        try:
            csv_path = _find_symbol_csv(csv_dir, sym_u)
        except Exception:
            csv_path = None

        if csv_path is None or not csv_path.exists():
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof,
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": "",
                }
            )
            continue

        ohlc = load_ohlcv_1h(csv_path, tz=None)
        if ohlc.empty or "high" not in ohlc.columns or "low" not in ohlc.columns:
            cov_rows.append(
                {
                    "scope": scope_id,
                    "split": str(split_filter).strip(),
                    "symbol": sym_u,
                    "profile": prof,
                    "entries": float(len(merged)),
                    "priced": 0.0,
                    "priced_pct": 0.0,
                    "csv_path": str(csv_path),
                }
            )
            continue

        entry_fields = _compute_entry_fields_1h(ohlc)
        idx = ohlc.index
        if getattr(idx, "tz", None) is None:
            idx_utc = idx.tz_localize("UTC")
        else:
            idx_utc = idx.tz_convert("UTC")
        ts_ns = idx_utc.view("int64")
        low_arr = pd.to_numeric(ohlc["low"], errors="coerce").to_numpy(dtype=float)
        high_arr = pd.to_numeric(ohlc["high"], errors="coerce").to_numpy(dtype=float)

        entry_ns = pd.to_datetime(merged["min_entry_time"], utc=True, errors="coerce").astype("int64")
        exit_ns = pd.to_datetime(merged["max_exit_time"], utc=True, errors="coerce").astype("int64")
        entry_px = pd.to_numeric(merged["entry"], errors="coerce")
        atr0 = pd.to_numeric(merged.get("atr", pd.Series(index=merged.index)), errors="coerce")
        side_s = merged["side"].astype(str).str.strip().str.upper()

        mae_atr: List[float] = []
        bucket_vals: List[float] = []
        priced = 0

        for i in range(int(len(merged))):
            en = entry_ns.iloc[i]
            ex = exit_ns.iloc[i]
            ep = entry_px.iloc[i]
            a0 = atr0.iloc[i]
            if pd.isna(en) or pd.isna(ex) or pd.isna(ep) or pd.isna(a0) or float(a0) <= 0.0:
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue
            si = int(np.searchsorted(ts_ns, int(en), side="left"))
            ei = int(np.searchsorted(ts_ns, int(ex), side="right"))
            if si < 0:
                si = 0
            if ei > int(len(ts_ns)):
                ei = int(len(ts_ns))
            if not (0 <= si < ei <= int(len(ts_ns))):
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue
            lo = float(np.nanmin(low_arr[si:ei]))
            hi = float(np.nanmax(high_arr[si:ei]))
            if not (np.isfinite(lo) and np.isfinite(hi)):
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue

            s0 = side_s.iloc[i]
            if s0 == "SHORT":
                mae = (hi - float(ep)) / float(a0)
            else:
                mae = (float(ep) - lo) / float(a0)

            j = int(np.searchsorted(ts_ns, int(en), side="right")) - 1
            c0 = float(entry_fields["cci"].iloc[j]) if ("cci" in entry_fields.columns and 0 <= j < int(len(entry_fields))) else float("nan")
            if not np.isfinite(c0):
                mae_atr.append(float("nan"))
                bucket_vals.append(float("nan"))
                continue

            favor = float(c0) if s0 == "SHORT" else float(-c0)
            b0 = int(
                np.select(
                    [favor <= -cci_level, favor <= 0.0, favor < cci_level],
                    [0, 1, 2],
                    default=3,
                )
            )
            mae_atr.append(float(mae))
            bucket_vals.append(float(b0))
            priced += 1

        merged = merged.copy()
        merged["profile"] = prof
        merged["trade_mae_atr"] = mae_atr
        merged["cci_basic_favor_bucket_1h"] = bucket_vals

        cov_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": prof,
                "entries": float(len(merged)),
                "priced": float(priced),
                "priced_pct": float(priced) / float(len(merged)) if len(merged) else 0.0,
                "csv_path": str(csv_path),
            }
        )

        x = pd.to_numeric(merged["cci_basic_favor_bucket_1h"], errors="coerce")
        mae = pd.to_numeric(merged["trade_mae_atr"], errors="coerce")
        m = x.notna() & mae.notna()
        dff = merged[m].copy()
        if dff.empty:
            continue

        if keep_set:
            keep = dff[dff["cci_basic_favor_bucket_1h"].astype(int).isin(sorted(keep_set))].copy()
            drop = dff[~dff["cci_basic_favor_bucket_1h"].astype(int).isin(sorted(keep_set))].copy()
        else:
            keep = dff[dff["cci_basic_favor_bucket_1h"].astype(float) != float(drop_bucket)].copy()
            drop = dff[dff["cci_basic_favor_bucket_1h"].astype(float) == float(drop_bucket)].copy()
        if int(len(keep)) < int(min_n) or int(len(drop)) < int(min_n):
            continue

        def _agg(g: pd.DataFrame) -> Dict[str, float]:
            return {
                "n": float(len(g)),
                "avg_pnl": float(pd.to_numeric(g["trade_pnl"], errors="coerce").mean()),
                "stop_loss_rate": float(pd.to_numeric(g["stop_loss_any"], errors="coerce").mean()),
                "mae_atr_mean": float(pd.to_numeric(g["trade_mae_atr"], errors="coerce").mean()),
                "hold_hours_median": float(pd.to_numeric(g["hold_hours"], errors="coerce").median()),
            }

        a = _agg(dff)
        b = _agg(keep)

        pair_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "symbol": sym_u,
                "profile": prof,
                "feature": "cci_basic_favor_bucket_1h",
                "drop_bucket": int(drop_bucket),
                "keep_buckets": keep_buckets,
                "n_total": a["n"],
                "n_keep": b["n"],
                "keep_pct": float(b["n"] / a["n"]) if a["n"] else float("nan"),
                "avg_pnl_total": a["avg_pnl"],
                "avg_pnl_keep": b["avg_pnl"],
                "stop_loss_rate_total": a["stop_loss_rate"],
                "stop_loss_rate_keep": b["stop_loss_rate"],
                "mae_atr_mean_total": a["mae_atr_mean"],
                "mae_atr_mean_keep": b["mae_atr_mean"],
                "hold_hours_median_total": a["hold_hours_median"],
                "hold_hours_median_keep": b["hold_hours_median"],
                "delta_avg_pnl": float(b["avg_pnl"] - a["avg_pnl"]),
                "delta_stop_loss_rate": float(b["stop_loss_rate"] - a["stop_loss_rate"]),
                "delta_mae_atr_mean": float(b["mae_atr_mean"] - a["mae_atr_mean"]),
                "pnl_better": float(b["avg_pnl"] > a["avg_pnl"]),
                "stop_loss_better": float(b["stop_loss_rate"] < a["stop_loss_rate"]),
                "mae_better": float(b["mae_atr_mean"] < a["mae_atr_mean"]),
                "both_risk_better": float((b["stop_loss_rate"] < a["stop_loss_rate"]) and (b["mae_atr_mean"] < a["mae_atr_mean"])),
            }
        )

    pd.DataFrame(cov_rows).to_csv(out_cov, index=False, encoding="utf-8-sig")
    pairs_df = pd.DataFrame(pair_rows)
    if pairs_df.empty:
        pairs_df = pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "drop_bucket",
                "keep_buckets",
                "n_total",
                "n_keep",
                "keep_pct",
                "avg_pnl_total",
                "avg_pnl_keep",
                "stop_loss_rate_total",
                "stop_loss_rate_keep",
                "mae_atr_mean_total",
                "mae_atr_mean_keep",
                "hold_hours_median_total",
                "hold_hours_median_keep",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_mae_atr_mean",
                "pnl_better",
                "stop_loss_better",
                "mae_better",
                "both_risk_better",
            ]
        )
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    sum_rows: List[Dict[str, object]] = []
    if not pairs_df.empty:
        sum_rows.append(
            {
                "scope": scope_id,
                "split": str(split_filter).strip(),
                "feature": "cci_basic_favor_bucket_1h",
                "drop_bucket": int(drop_bucket),
                "keep_buckets": keep_buckets,
                "n_pairs": float(len(pairs_df)),
                "frac_pnl_better": float(pd.to_numeric(pairs_df["pnl_better"], errors="coerce").mean()),
                "frac_stop_loss_better": float(pd.to_numeric(pairs_df["stop_loss_better"], errors="coerce").mean()),
                "frac_mae_better": float(pd.to_numeric(pairs_df["mae_better"], errors="coerce").mean()),
                "frac_both_risk_better": float(pd.to_numeric(pairs_df["both_risk_better"], errors="coerce").mean()),
                "median_keep_pct": float(pd.to_numeric(pairs_df["keep_pct"], errors="coerce").median()),
            }
        )
    sum_df = pd.DataFrame(sum_rows)
    if sum_df.empty:
        sum_df = pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "drop_bucket",
                "keep_buckets",
                "n_pairs",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_mae_better",
                "frac_both_risk_better",
                "median_keep_pct",
            ]
        )
    sum_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum, "COVERAGE": out_cov}


def _run_code4_followups_generic(
    *,
    bucket_stats_csv: Path,
    out_dir: Path,
    prefix: str,
    scope: str,
    split_filter: str,
    min_n: float,
    profile_merge: bool,
    date_tag: str,
) -> Dict[str, Path]:
    bucket_stats_csv = Path(bucket_stats_csv)
    out_dir = Path(out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    df = pd.read_csv(bucket_stats_csv)
    out_pairs = out_dir / f"{prefix}_stability_pairs_{date_tag}_v1.csv"
    out_sum = out_dir / f"{prefix}_stability_summary_{date_tag}_v1.csv"

    if df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "symbol",
                "profile",
                "feature",
                "scheme",
                "group_a",
                "group_b",
                "n_a",
                "n_b",
                "avg_pnl_a",
                "avg_pnl_b",
                "stop_loss_rate_a",
                "stop_loss_rate_b",
                "win_rate_a",
                "win_rate_b",
                "tp2_rate_a",
                "tp2_rate_b",
                "delta_avg_pnl",
                "delta_stop_loss_rate",
                "delta_win_rate",
                "sufficient",
                "notes",
            ]
        ).to_csv(out_pairs, index=False, encoding="utf-8-sig")
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    scope_id = str(scope).strip()
    split_id = str(split_filter).strip()
    if "scope" in df.columns and scope_id:
        df = df[df["scope"].astype(str).eq(scope_id)].copy()
    if "split" in df.columns and split_id:
        df = df[df["split"].astype(str).eq(split_id)].copy()

    if profile_merge and "profile" in df.columns:
        df["profile"] = "A_all"

    for c in ["n_trades", "win_rate", "avg_pnl", "stop_loss_rate", "tp2_rate"]:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors="coerce")

    def _wmean(x: pd.Series, w: pd.Series) -> float:
        m = x.notna() & w.notna() & (w > 0)
        if not bool(m.any()):
            return float("nan")
        return float((x[m] * w[m]).sum() / w[m].sum())

    def _agg_rows(g: pd.DataFrame) -> Dict[str, float]:
        w = g["n_trades"]
        return {
            "n": float(w.sum()),
            "avg_pnl": _wmean(g["avg_pnl"], w),
            "stop_loss_rate": _wmean(g["stop_loss_rate"], w),
            "win_rate": _wmean(g["win_rate"], w),
            "tp2_rate": _wmean(g["tp2_rate"], w),
        }

    def _code4_idx(bucket: object) -> Optional[int]:
        s = str(bucket)
        m = re.search(r"code4=(\d+)$", s)
        if not m:
            return None
        try:
            return int(m.group(1))
        except Exception:
            return None

    pair_rows: List[Dict[str, object]] = []
    min_n = float(min_n)

    for (sym, prof, feat, scheme), sub in df.groupby(["symbol", "profile", "feature", "scheme"], sort=True):
        if str(scheme) != "code4":
            continue
        sub2 = sub.copy()
        sub2["_code"] = sub2["bucket"].map(_code4_idx)
        sub2 = sub2[sub2["_code"].notna()].copy()
        if sub2.empty:
            continue
        sub2["_code"] = sub2["_code"].astype(int)
        if int(sub2["_code"].nunique()) < 2:
            continue

        max_code = int(sub2["_code"].max())
        if max_code >= 2 and str(feat).endswith("_score_1h"):
            a = sub2[sub2["_code"] <= 0].copy()
            b = sub2[sub2["_code"] >= 1].copy()
            if a.empty or b.empty:
                continue
            a2 = _agg_rows(a)
            b2 = _agg_rows(b)
            sufficient = bool(a2["n"] >= min_n and b2["n"] >= min_n)
            pair_rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "symbol": str(sym),
                    "profile": str(prof),
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "group_a": "code4=0",
                    "group_b": "code4>=1",
                    "n_a": float(a2["n"]),
                    "n_b": float(b2["n"]),
                    "avg_pnl_a": float(a2["avg_pnl"]),
                    "avg_pnl_b": float(b2["avg_pnl"]),
                    "stop_loss_rate_a": float(a2["stop_loss_rate"]),
                    "stop_loss_rate_b": float(b2["stop_loss_rate"]),
                    "win_rate_a": float(a2["win_rate"]),
                    "win_rate_b": float(b2["win_rate"]),
                    "tp2_rate_a": float(a2["tp2_rate"]),
                    "tp2_rate_b": float(b2["tp2_rate"]),
                    "delta_avg_pnl": float(float(b2["avg_pnl"]) - float(a2["avg_pnl"])),
                    "delta_stop_loss_rate": float(float(b2["stop_loss_rate"]) - float(a2["stop_loss_rate"])),
                    "delta_win_rate": float(float(b2["win_rate"]) - float(a2["win_rate"])),
                    "sufficient": int(sufficient),
                    "notes": "merged_0_vs_ge1",
                }
            )
            continue

        lo = sub2.loc[sub2["_code"].idxmin()]
        hi = sub2.loc[sub2["_code"].idxmax()]
        aa = _agg_rows(sub2[sub2["_code"].eq(int(lo["_code"]))].copy())
        bb = _agg_rows(sub2[sub2["_code"].eq(int(hi["_code"]))].copy())
        sufficient = bool(aa["n"] >= min_n and bb["n"] >= min_n)
        pair_rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "symbol": str(sym),
                "profile": str(prof),
                "feature": str(feat),
                "scheme": str(scheme),
                "group_a": str(lo["bucket"]),
                "group_b": str(hi["bucket"]),
                "n_a": float(aa["n"]),
                "n_b": float(bb["n"]),
                "avg_pnl_a": float(aa["avg_pnl"]),
                "avg_pnl_b": float(bb["avg_pnl"]),
                "stop_loss_rate_a": float(aa["stop_loss_rate"]),
                "stop_loss_rate_b": float(bb["stop_loss_rate"]),
                "win_rate_a": float(aa["win_rate"]),
                "win_rate_b": float(bb["win_rate"]),
                "tp2_rate_a": float(aa["tp2_rate"]),
                "tp2_rate_b": float(bb["tp2_rate"]),
                "delta_avg_pnl": float(float(bb["avg_pnl"]) - float(aa["avg_pnl"])),
                "delta_stop_loss_rate": float(float(bb["stop_loss_rate"]) - float(aa["stop_loss_rate"])),
                "delta_win_rate": float(float(bb["win_rate"]) - float(aa["win_rate"])),
                "sufficient": int(sufficient),
                "notes": "",
            }
        )

    pairs_df = pd.DataFrame(pair_rows)
    pairs_df.to_csv(out_pairs, index=False, encoding="utf-8-sig")

    if pairs_df.empty:
        pd.DataFrame(
            columns=[
                "scope",
                "split",
                "feature",
                "scheme",
                "n_pairs",
                "n_sufficient",
                "frac_pnl_better",
                "frac_stop_loss_better",
                "frac_both",
                "notes",
            ]
        ).to_csv(out_sum, index=False, encoding="utf-8-sig")
        return {"PAIRS": out_pairs, "SUMMARY": out_sum}

    suff = pd.to_numeric(pairs_df["sufficient"], errors="coerce").fillna(0.0).astype(int).eq(1)
    rows = []
    for (feat, scheme), g in pairs_df.groupby(["feature", "scheme"], dropna=False, sort=False):
        gg = g[suff.loc[g.index]].copy()
        if gg.empty:
            rows.append(
                {
                    "scope": scope_id,
                    "split": split_id,
                    "feature": str(feat),
                    "scheme": str(scheme),
                    "n_pairs": float(len(g)),
                    "n_sufficient": 0.0,
                    "frac_pnl_better": float("nan"),
                    "frac_stop_loss_better": float("nan"),
                    "frac_both": float("nan"),
                    "notes": "no sufficient pairs",
                }
            )
            continue
        pnl_better = pd.to_numeric(gg["delta_avg_pnl"], errors="coerce") > 0.0
        sl_better = pd.to_numeric(gg["delta_stop_loss_rate"], errors="coerce") < 0.0
        rows.append(
            {
                "scope": scope_id,
                "split": split_id,
                "feature": str(feat),
                "scheme": str(scheme),
                "n_pairs": float(len(g)),
                "n_sufficient": float(len(gg)),
                "frac_pnl_better": float(pnl_better.mean()),
                "frac_stop_loss_better": float(sl_better.mean()),
                "frac_both": float((pnl_better & sl_better).mean()),
                "notes": "",
            }
        )
    summary_df = pd.DataFrame(rows)
    summary_df.to_csv(out_sum, index=False, encoding="utf-8-sig")
    return {"PAIRS": out_pairs, "SUMMARY": out_sum}


